  'É o nome que todos veem no Syden. Para entrar e nas menções com @, continua valendo o nome da conta.': 'Èyí ni orúkọ tí gbogbo ènìyàn ń rí lórí Syden. Fún wíwọlé àti ìtọ́kasí pẹ̀lú @, orúkọ àkántì ṣì ni a ń lò.',
