  'Desconecta o Syden em todos os outros computadores e celulares. Você continua conectado aqui.': 'Ó ń jáde kúrò nínú Syden ní gbogbo kọ̀ǹpútà àti fóònù mìíràn. Ẹ ṣì wà nínú rẹ̀ níbí.',
