  'Descrição': 'Àpèjúwe',
  'Desligado, a transmissão de quem está na sala aparece como convite e só começa a ser baixada quando você clica em Assistir. Isso poupa internet e processador — principalmente em sala cheia.': 'Tí ó bá kú, ìfihàn ẹni tó wà nínú yàrá yóò farahàn bí ìpè, yóò sì bẹ̀rẹ̀ sí ní gbígbà wọlé nígbà tí ẹ bá tẹ Wò ó nìkan. Èyí ń dín ìntánẹ́ẹ̀tì àti ẹ̀rọ ìṣiṣẹ́ kù — pàápàá nínú yàrá tó kún.',
  'Desligar câmera': 'Pa kámẹ́rà',
