  'Diga o e-mail da sua conta e mandamos um link para escolher outra.': 'Ẹ sọ ímeèlì àkáǹtì yín, a ó sì fi ọ̀nà ránṣẹ́ láti yan òmíràn.',
  'Digite sua senha para confirmar': 'Ẹ tẹ ọ̀rọ̀ aṣínà yín láti fìdí rẹ̀ múlẹ̀',
