  'Do laranja ao vermelho, como carvão aceso.': 'Láti ọsàn sí pupa, bí ẹyín iná tó jó.',
  'Dois emojis com o mesmo nome: cada um precisa do seu.': 'Émọ́jì méjì tó ní orúkọ kan náà: ọ̀kọ̀ọ̀kan gbọdọ̀ ní tirẹ̀.',
  'Dono': 'Olórí',
  'Dono da comunidade': 'Olórí àwùjọ',
  'Dourado com brilho que passa devagar.': 'Wúrà pẹ̀lú ìtànṣán tó ń kọjá lọ́ra.',
  'Durante uma chamada, esse botão toca estes sons para todos na sala. Instale pacotes prontos ou envie os seus; o que é seu favorito fica na frente do painel.': 'Nígbà ìpè, bọ́tìnì yìí ń tẹ àwọn ìró wọ̀nyí fún gbogbo ènìyàn nínú yàrá. Ẹ fi àwọn ìdì tó ṣetán sílẹ̀ tàbí kí ẹ fi tiyín ránṣẹ́; èyí tí ẹ fẹ́ràn jùlọ yóò wà níwájú pátákó náà.',
  'É a primeira coisa que alguém vê ao entrar na comunidade, uma vez só. Sem isto, a pessoa cai direto na lista de canais.': 'Òun ni ohun àkọ́kọ́ tí ẹnìkan rí nígbà tó bá wọ àwùjọ, ẹ̀ẹ̀kan ṣoṣo. Láìsí èyí, ẹni náà yóò bọ́ sí inú àtòjọ ikànnì tààrà.',
  'É assim que os outros veem você na lista e nas conversas.': 'Bẹ́ẹ̀ ni àwọn yòókù ṣe ń rí yín nínú àtòjọ àti nínú ìbánisọ̀rọ̀.',
