  'Estrelas necessárias': 'Ìràwọ̀ tí a nílò',
  'Quando uma mensagem junta estrelas ⭐ suficientes, o Syden a publica no canal de destaques. A estrela de quem escreveu não conta, e apagar a mensagem apaga o destaque.': 'Tí ọ̀rọ̀ kan bá kó ìràwọ̀ ⭐ tó tó, Syden á gbé e jáde nínú ìkànnì àṣàyàn. Ìràwọ̀ ẹni tó kọ ọ́ kò ka, píparẹ́ ọ̀rọ̀ náà sì ń pa àṣàyàn rẹ́ pẹ̀lú.',
