  'O Syden anuncia o prêmio no canal, e quem quiser participar reage com 🎉. Na hora marcada, ele sorteia entre quem reagiu e publica o resultado.': 'Syden á kéde ẹ̀bùn náà nínú ìkànnì, ẹni tó bá fẹ́ kópa á fèsì pẹ̀lú 🎉. Ní àkókò tí a yàn, á fa ìfàmìsí láàrin àwọn tó fèsì, á sì gbé èsì jáde.',
