  'Hoje é aniversário de {pessoa}! 🎉 Parabéns!': 'Òní ni ọjọ́ ìbí {pessoa}! 🎉 Ẹ kú ọjọ́ ìbí!',
  'Mês': 'Oṣù',
  'No dia do aniversário de quem informou a data, o Syden publica os parabéns no canal escolhido. Use {pessoa} no lugar do nome.': 'Ní ọjọ́ ìbí ẹni tó fi ọjọ́ rẹ̀ sílẹ̀, Syden á gbé ìkíni jáde nínú ìkànnì tí a yàn. Lo {pessoa} dípò orúkọ.',
  'Só o dia e o mês, nunca o ano. As comunidades que avisam aniversários dão os parabéns no dia. É opcional, e dá para apagar quando quiser.': 'Ọjọ́ àti oṣù nìkan, kì í ṣe ọdún rárá. Àwọn àwùjọ tó ń kéde ọjọ́ ìbí á kí ọ ní ọjọ́ náà. Kò pọndandan, o sì lè pa á rẹ́ nígbàkigbà.',
