  'Regras': 'Àwọn òfin',
  'Regras que o Syden aplica sozinho, antes de a mensagem aparecer. Quem administra não passa por elas. A mensagem barrada volta para quem escreveu, com o motivo, e ninguém mais a vê.': 'Àwọn òfin tí Syden fúnra rẹ̀ ń lò kí ìfiránṣẹ́ tó farahàn. Kò kan àwọn alábòójútó. Ìfiránṣẹ́ tí a dí padà sọ́dọ̀ ẹni tó kọ ọ́, pẹ̀lú ìdí, kò sì sí ẹlòmíràn tó rí i.',
  'Salvo.': 'A ti fi pamọ́.',
  'Uma por linha. Vale a palavra inteira, sem diferença de acento ou de maiúscula: proibir uma palavra não barra outra mais longa que só a contenha.': 'Ọ̀kan ní ìlà kọ̀ọ̀kan. Gbogbo ọ̀rọ̀ ni a ń kà, láìka àmì tàbí lẹ́tà ńlá sí: kíkà ọ̀rọ̀ kan léèwọ̀ kò dí ọ̀rọ̀ tó gùn jù tó kàn ní i nínú.',
