  'Não perturbe': 'Má dà mí láàmú',
  'Não se compra: conquista-se.': 'A kì í rà á: a ń jẹ ẹ́ gbà.',
  'Nebulosa': 'Ẹ̀kúrú ìràwọ̀',
  'Nenhum GIF para essa busca.': 'Kò sí GIF fún ìwádìí yìí.',
  'Nenhum pacote ainda. Monte o primeiro com imagens suas, ou publique os emojis que esta comunidade já tem.': 'Kò sí ìdì kankan síbẹ̀. Ẹ gbé àkọ́kọ́ kalẹ̀ pẹ̀lú àwọn àwòrán yín, tàbí kí ẹ tẹ àwọn émọ́jì tí àwùjọ yìí ti ní jáde.',
  'Nenhum som com esse nome.': 'Kò sí ìró tó ní orúkọ yìí.',
  'Nenhuma denúncia até agora.': 'Kò sí ẹ̀sùn kankan títí di báyìí.',
  'Nenhuma música ainda. Suba um arquivo que você tenha aí para a turma cantar.': 'Kò sí orin kankan síbẹ̀. Ẹ gbé fáìlì tí ẹ ní wọlé kí àwọn ọ̀rẹ́ lè kọrin.',
  'Ninguém abriu a sua transmissão ainda. O Syden só codifica a imagem quando alguém assiste — por isso não há números aqui.': 'Kò sí ẹni tó ṣí ìfihàn yín síbẹ̀. Syden ń ṣe àwòrán náà nígbà tí ẹnìkan bá ń wò ó nìkan — ìdí nìyí tí kò fi sí nọ́ńbà níbí.',
  'Ninguém com a palavra ainda': 'Kò sí ẹni tó ní ọ̀rọ̀ síbẹ̀',
  'Ninguém é avisado de que foi bloqueado.': 'A kì í sọ fún ẹnikẹ́ni pé a ti dí i lọ́nà.',
  'Ninguém entrou em chamada este mês ainda.': 'Kò sí ẹni tó wọ ìpè ní oṣù yìí síbẹ̀.',
  'Ninguém mais nesta comunidade ainda.': 'Kò sí ẹlòmíràn nínú àwùjọ yìí síbẹ̀.',
  'Ninguém na chamada — seja o primeiro': 'Kò sí ẹni nínú ìpè — ẹ jẹ́ ẹni àkọ́kọ́',
  'Ninguém para sugerir por enquanto — entre numa comunidade para conhecer gente.': 'Kò sí ẹni tí a lè dámọ̀ràn fún yín lọ́wọ́lọ́wọ́ — ẹ wọ àwùjọ kan láti mọ ènìyàn.',
  'Ninguém respondeu neste tópico ainda.': 'Kò sí ẹni tó dáhùn nínú òkùn yìí síbẹ̀.',
