  'Dia e noite': 'Ọ̀sán àti òru',
  'O avatar limpo, como sempre foi.': 'Àwòrán mímọ́, bí ó ti rí nígbà gbogbo.',
  'O canal sai da vista de todos com as mensagens dentro. Dá para trazer de volta por {dias} dias, em Configurações → Comunidade → Lixeira.': 'Ikànnì náà ń kúrò lójú gbogbo ènìyàn pẹ̀lú ìfiránṣẹ́ inú rẹ̀. Ẹ lè mú un padà fún ọjọ́ {dias}, ní Ètò → Àwùjọ → Pàǹtí.',
  'O cartão liso.': 'Káàdì tó ṣófo.',
  'O céu inteiro girando bem devagar.': 'Gbogbo ojú ọ̀run tó ń yí lọ́ra gan-an.',
  'O clipe ficou grande demais para o chat. Escolha um trecho menor.': 'Gígé náà tóbi jù fún ìbánisọ̀rọ̀. Ẹ yan apá kékeré.',
  'O navegador bloqueou as notificações deste site. Libere no cadeado ao lado do endereço e recarregue a página.': 'Awáròyìn náà ti dí àwọn ìkìlọ̀ ojú òpó yìí lọ́nà. Ẹ tú u sílẹ̀ nínú àpótí ìhámọ́ lẹ́gbẹ̀ẹ́ àdírẹ́sì, kí ẹ sì tún ojú ìwé náà gbé wọlé.',
  'o nome exato da pessoa': 'orúkọ gan-an ti ẹni náà',
  'O nome muda de cor devagar.': 'Orúkọ náà ń yí àwọ̀ padà lọ́ra.',
  'O que aconteceu?': 'Kí ló ṣẹlẹ̀?',
  'O que dizer': 'Ohun tí a ó sọ',
  'O que tem dentro': 'Ohun tó wà nínú rẹ̀',
  'O que tem dentro do pacote': 'Ohun tó wà nínú ìdì náà',
  'O que vamos jogar hoje?': 'Kí ni a ó ṣeré lónìí?',
  'O que você fez a respeito?': 'Kí ni ẹ ṣe nípa rẹ̀?',
  'O selo aparece aqui quando o primeiro marco cair. Até lá ele fica guardado — e chegar nele é justamente o que ele vai significar.': 'Èdìdì náà yóò farahàn níbí nígbà tí àmì àkọ́kọ́ bá ṣubú. Títí di ìgbà náà ó wà ní pamọ́ — dídé bá a sì ni ohun tí yóò túmọ̀ sí.',
  'O selo desta comunidade é': 'Èdìdì àwùjọ yìí ni ',
  'O som chega quando você abre esta transmissão.': 'Ohùn náà ń dé nígbà tí ẹ bá ṣí ìfihàn yìí.',
  'O survival do Léo': 'Ìyè Léo',
  'O Syden já sabe escrever em qualquer uma destas línguas — falta a tradução dos textos. Enquanto ela não chega, o que não estiver traduzido aparece em português, e as letras de cada alfabeto aparecem certas, sem quadradinhos.': 'Syden ti mọ bí a ṣe ń kọ ní èyíkéyìí nínú àwọn èdè wọ̀nyí — ìtumọ̀ àwọn ọ̀rọ̀ ló ṣẹ́kù. Títí ó fi dé, ohun tí a kò tíì tú itumọ̀ rẹ̀ yóò farahàn ní èdè Pọtogí, àwọn lẹ́tà álífábẹ́ẹ̀tì kọ̀ọ̀kan yóò sì hàn dáadáa, láìsí àpótí kékeré.',
  'O Syden vai ficar fora do ar por uns 10 minutos para uma atualização.': 'Syden yóò kúrò lórí afẹ́fẹ́ fún nǹkan bí ìṣẹ́jú 10 fún àtúnṣe.',
  'Observação': 'Àkíyèsí',
  'Oceania': 'Òṣíáníà',
  'Oceano': 'Òkun',
  'Offline': 'Kò sí lórí ayélujára',
  'Olhe o seu e-mail': 'Ẹ wo ímeèlì yín',
  'Opções': 'Àwọn àṣàyàn',
  'Os marcos abaixo foram escolhidos para não haver como alcançá-los sozinho — todos precisam de mais de uma pessoa, ao longo do tempo.': 'A yan àwọn àmì ìsàlẹ̀ wọ̀nyí kí ẹnìkan má bàa lè dé bá wọn nìkan — gbogbo wọn ní ju ènìyàn kan lọ, ní àsìkò gbígùn.',
  'Os outros idiomas': 'Àwọn èdè yòókù',
  'Os outros passam a ouvir o efeito na hora. Você continua sem se escutar.': 'Àwọn yòókù yóò bẹ̀rẹ̀ sí gbọ́ ìpa náà lẹ́sẹ̀kẹsẹ̀. Ẹ ṣì kò ní gbọ́ ara yín.',
