  'Senha atual': 'Ọ̀rọ̀ aṣínà lọ́wọ́lọ́wọ́',
  'Senha definida. Agora dá para entrar com nome e senha também.': 'A ti ṣètò ọ̀rọ̀ aṣínà. Báyìí ẹ lè wọlé pẹ̀lú orúkọ àti ọ̀rọ̀ aṣínà pẹ̀lú.',
  'Senha trocada': 'A ti yí ọ̀rọ̀ aṣínà padà',
  'Senha:': 'Ọ̀rọ̀ aṣínà:',
  'Seria bom se…': 'Yóò dára tí…',
  'Seu microfone está bloqueado: ninguém está te ouvindo.': 'Wọ́n ti dí máíkírófóònù yín: kò sí ẹni tó ń gbọ́ yín.',
  'Quem bloqueia é o Windows. Abra Configurações do Windows → Privacidade e segurança → Microfone e ligue o acesso para o navegador.': 'Windows ló ń dí i. Ẹ ṣí Ètò Windows → Àṣírí àti ààbò → Máíkírófóònù kí ẹ sì tan ààyè fún aṣàwákiri.',
  'Clique no ícone à esquerda do endereço do site, ative o Microfone, e o Syden liga sozinho.': 'Ẹ tẹ àmì tó wà ní òsì àdírẹ́sì ojú-òpó, ẹ tan Máíkírófóònù, Syden yóò sì tàn án fúnra rẹ̀.',
  'Seu microfone não está mandando som: ninguém está te ouvindo. Clique para escolher outro.': 'Máíkírófóònù yín kò fi ohùn ránṣẹ́: kò sí ẹni tó ń gbọ́ yín. Ẹ tẹ̀ ẹ́ láti yan òmíràn.',
  'Buscando…': 'Ó ń mú un wá…',
  'Buscar': 'Mú wá',
  'Link do som': 'Ìjápọ̀ ìró',
  'ou cole um link (MyInstants, por exemplo)': 'tàbí ẹ lẹ ìjápọ̀ kan (láti MyInstants, fún àpẹẹrẹ)',
  'Ouça antes de enviar:': 'Ẹ tẹ́tí sí i kí ẹ tó fi ránṣẹ́:',
  'Não achei o áudio dessa página. No MyInstants, copie o link do botão de baixar e cole aqui.': 'A kò rí ìró ojú-ewé yẹn. Lórí MyInstants, ẹ ṣe ẹ̀dà ìjápọ̀ bọ́tìnnì ìgbàsílẹ̀ kí ẹ sì lẹ̀ ẹ́ síbí.',
  'Esse endereço não é de um arquivo de áudio.': 'Àdírẹ́sì yìí kì í ṣe fáìlì ohùn.',
  'Caixa de ideias (como os outros veem)': 'Àpótí èrò (bí àwọn míì ṣe ń rí i)',
  'Entre numa comunidade para ver as salas.': 'Ẹ darapọ̀ mọ́ àwùjọ kan láti rí àwọn yàrá rẹ̀.',
  'Escreva um pouco mais sobre a sua ideia.': 'Ẹ kọ díẹ̀ sí i nípa èrò yín.',
