  'vazia': 'òfo',
  'Serve para recuperar a senha e para avisar você se algo acontecer com o Syden. Sem e-mail, uma senha esquecida não tem volta.': 'Ó wúlò fún gbígba ọ̀rọ̀ aṣínà padà àti fún kíkìlọ̀ fún yín tí nǹkan bá ṣẹlẹ̀ sí Syden. Láìsí ímeèlì, ọ̀rọ̀ aṣínà tí a gbàgbé kò ní ìpadàbọ̀.',
  'Servidores de jogos': 'Àwọn sáfà eré',
