  'Sua transmissão está sem som. O navegador só manda o som se você marcar “compartilhar áudio” na janelinha de escolher a tela.': 'Ìfihàn yín kò ní ohùn. Awáròyìn náà ń fi ohùn ránṣẹ́ nígbà tí ẹ bá sàmì sí “pín ohùn” nínú fèrèsé kékeré ìyan ojú ìwé nìkan.',
  'Sua voz': 'Ohùn yín',
  'Suba músicas que você já tem. Um arquivo': 'Ẹ gbé àwọn orin tí ẹ ti ní wọlé. Fáìlì ',
  'Suba só o que é seu ou o que você tem direito de usar. Ter o arquivo não é o mesmo que ter direito de tocar para outras pessoas.': 'Ẹ gbé ohun tí í ṣe tiyín nìkan wọlé, tàbí èyí tí ẹ ní ẹ̀tọ́ láti lò. Níní fáìlì kò dọ́gba pẹ̀lú níní ẹ̀tọ́ láti tẹ̀ ẹ́ fún àwọn ẹlòmíràn.',
  'Sugestões de melhoria': 'Àwọn àbá ìtẹ̀síwájú',
  'Supressão de ruído': 'Ìdínkù ariwo',
  'Também dá para arrastar a borda de cada barra na tela. Dois cliques na borda volta ao padrão.': 'Ẹ tún lè fa ẹ̀gbẹ́ ìlà kọ̀ọ̀kan lórí ojú ìwé. Ìtẹ̀ méjì lórí ẹ̀gbẹ́ náà ń mú un padà sí ìpilẹ̀.',
  'Também de graça, e também trocáveis quando quiser. Ficam nas configurações da comunidade, porque valem para a comunidade inteira e não só para você.': 'Lọ́fẹ̀ẹ́ pẹ̀lú, a sì lè yí wọn padà nígbàkúgbà. Wọ́n wà nínú ètò àwùjọ, nítorí pé wọ́n wúlò fún gbogbo àwùjọ, kì í ṣe fún yín nìkan.',
