  'Toca um som quando alguém entra ou sai da sua sala, quando alguém começa a compartilhar a tela e quando você silencia ou ensurdece.': 'Ó ń tẹ ìró nígbà tí ẹnìkan bá wọ yàrá yín tàbí tí ó bá kúrò, nígbà tí ẹnìkan bá bẹ̀rẹ̀ sí pín ojú ìwé, àti nígbà tí ẹ bá pa ohùn tàbí tí ẹ bá di etí.',
  'Tocando…': 'Ó ń tẹ̀…',
  'Todas as cores girando devagar. A mais chamativa de todas.': 'Gbogbo àwọ̀ tó ń yí lọ́ra. Èyí tó fa ojú mọ́ra jùlọ nínú gbogbo rẹ̀.',
  'Todo mundo desta comunidade pode usar estes emojis escrevendo {exemplo} ou pelo botão de emoji do chat. Sem assinatura: está tudo liberado.': 'Gbogbo ènìyàn nínú àwùjọ yìí lè lo àwọn émọ́jì wọ̀nyí nípa kíkọ {exemplo} tàbí nípasẹ̀ bọ́tìnì émọ́jì ìbánisọ̀rọ̀. Láìsí ìforúkọsílẹ̀ oṣooṣù: gbogbo rẹ̀ ṣí sílẹ̀.',
  'Tom mais alto e mais claro.': 'Ohùn tó ga sí i, tó sì mọ́ sí i.',
