  'Um lugar novo, com canais próprios, e você decide quem entra.': 'Ibi tuntun kan, pẹ̀lú ikànnì tirẹ̀, ẹ sì ló ń pinnu ẹni tó ń wọlé.',
  'Um lugar novo, com canais próprios. Você escolhe quem entra pelo código de convite.': 'Ibi tuntun kan, pẹ̀lú ikànnì tirẹ̀. Ẹ ló ń yan ẹni tó ń wọlé nípasẹ̀ kóòdù ìpè.',
  'Um pacote instalado entra para toda a comunidade: os emojis dele passam a valer nas mensagens de todo mundo.': 'Ìdì tí a fi sílẹ̀ ń wọlé fún gbogbo àwùjọ: àwọn émọ́jì rẹ̀ yóò bẹ̀rẹ̀ sí ṣiṣẹ́ nínú ìfiránṣẹ́ gbogbo ènìyàn.',
  'Uma imagem larga, de 1200 por 300 ou parecida. GIF animado vale, e anima de verdade. Sem capa, fica a arte que você escolheu nas boas-vindas.': 'Àwòrán gbígbòòrò, ti 1200 ní 300 tàbí bẹ́ẹ̀. GIF alárìnrìn wúlò, ó sì ń rìn lóòótọ́. Láìsí ìbòrí, àwòrán tí ẹ yàn nínú ìkíni ni yóò wà.',
