  'Você entrou por um serviço de fora e ainda não tem senha nesta conta. Defina uma aqui: passa a valer como segundo jeito de entrar, e é o que permite desligar aquele serviço depois.': 'Ẹ wọlé nípasẹ̀ iṣẹ́ òde, ẹ kò sì tíì ní ọ̀rọ̀ aṣínà nínú àkáǹtì yìí. Ẹ ṣètò ọ̀kan níbí: yóò di ọ̀nà kejì láti wọlé, òun sì ni ohun tó ń jẹ́ kí ẹ pa iṣẹ́ yẹn lẹ́yìn náà.',
  'Você está silenciado!': 'A ti pa ohùn yín!',
  'Você foi convidado. É só escolher um nome, um e-mail e uma senha.': 'A ti pè yín. Ẹ kàn yan orúkọ kan, ímeèlì kan àti ọ̀rọ̀ aṣínà kan.',
