  'Você perde o acesso aos canais desta comunidade. Para voltar, vai precisar de um convite novo.': 'Ẹ ó pàdánù ìwọlé sí àwọn ikànnì àwùjọ yìí. Láti padà, ẹ ó nílò ìpè tuntun.',
