  'Esta pessoa excluiu a conta. As mensagens daqui não chegam a ninguém.': 'Ẹni yìí ti pa àkáǹtì rẹ̀ rẹ́. Àwọn ìfiránṣẹ́ láti ibí kò ní dé ọ̀dọ̀ ẹnikẹ́ni.',
  '🤖 Recado automático: sua ideia chegou, obrigado! Vou ler com calma. Se eu tiver dúvida, pergunto por aqui mesmo — e se ela entrar no Syden, você vai saber na hora.': '🤖 Ìkìlọ̀ àdáṣe: èrò yín ti dé, ẹ ṣé! Màá kà á pẹ̀lú ìfarabalẹ̀. Tí mo bá ní iyèméjì, màá bi yín léèrè níbí gan-an — tí ó bá sì wọ Syden, ẹ ó mọ̀ lẹ́sẹ̀kẹsẹ̀.',
