  'Outros jogos': 'Àwọn eré mìíràn',
  'Stop': 'Stop',
  'Sai uma letra e cada um escreve uma palavra com ela em cada categoria. Quem completar primeiro aperta STOP, e a turma decide o que vale.': 'Lẹ́tà kan yóò jáde, gbogbo ènìyàn yóò sì kọ ọ̀rọ̀ kan tó bẹ̀rẹ̀ pẹ̀lú rẹ̀ nínú ẹ̀ka kọ̀ọ̀kan. Ẹni tó bá kọ́kọ́ parí yóò tẹ STOP, àwọn ọ̀rẹ́ yóò sì pinnu èyí tó kà.',
  'Sudoku': 'Sudoku',
  'Todo mundo recebe o mesmo sudoku, e a sala vê quem está mais perto de terminar.': 'Gbogbo ènìyàn ló ń gba sudoku kan náà, yàrá náà sì ń rí ẹni tó sún mọ́ ìparí jù.',
  'Cinco em linha': 'Márùn-ún ní ìlà',
  'Duas pessoas põem pedras no tabuleiro, uma de cada vez. Vence quem fizer cinco seguidas. A sala assiste.': 'Ènìyàn méjì ń gbé òkúta sórí pátákó, ní ọ̀kọ̀ọ̀kan. Ẹni tó bá to márùn-ún tẹ̀léra ló borí. Yàrá ń wò ó.',
  'Mancala': 'Mancala',
  'O jogo de semear: pegue as sementes de uma casa e espalhe uma por casa. Vence quem guardar mais no depósito. A sala assiste.': 'Eré gbígbìn: mú àwọn irúgbìn inú ihò kan kí o sì fi ọ̀kọ̀ọ̀kan sínú ihò kọ̀ọ̀kan. Ẹni tó bá kó púpọ̀ jù sínú àpótí ìpamọ́ rẹ̀ ló borí. Yàrá ń wò ó.',
