  'Jogo desconhecido.': 'Eré tí a kò mọ̀.',
  'Entre na sala de voz para jogar com a turma.': 'Wọ yàrá ohùn láti ṣeré pẹ̀lú àwọn ọ̀rẹ́.',
  'Já tem uma partida acontecendo nesta sala.': 'Ìdíje kan ti ń lọ lọ́wọ́ nínú yàrá yìí.',
  'Só quem começou a partida pode encerrá-la antes do fim.': 'Ẹni tó bẹ̀rẹ̀ ìdíje nìkan ló lè parí rẹ̀ kí ó tó dópin.',
  'Lobisomem': 'Ìkookò-ènìyàn',
  'À noite, escolha com os outros lobisomens quem atacar. De dia, não deixe ninguém desconfiar.': 'Ní òru, bá àwọn ìkookò-ènìyàn yòókù yan ẹni tí ẹ ó kọlù. Ní ọ̀sán, má ṣe jẹ́ kí ẹnikẹ́ni fura.',
  'Vidente': 'Aríran',
  'À noite, descubra se alguém é lobisomem. Conte de dia, se achar que vale o risco.': 'Ní òru, wádìí bóyá ẹnìkan jẹ́ ìkookò-ènìyàn. Sọ ọ́ ní ọ̀sán, tí o bá rò pé ewu náà tọ́ sí i.',
  'Anjo': 'Áńgẹ́lì',
  'À noite, escolha alguém para proteger. Se os lobisomens atacarem essa pessoa, ela sobrevive.': 'Ní òru, yan ẹnìkan láti dáàbò bò. Tí àwọn ìkookò-ènìyàn bá kọlu ẹni náà, yóò yè.',
  'Da vila': 'Ará abúlé',
  'À noite, durma. De dia, descubra quem são os lobisomens e vote para tirá-los do jogo.': 'Ní òru, sùn. Ní ọ̀sán, wá àwọn ìkookò-ènìyàn rí kí o sì dìbò láti yọ wọ́n kúrò nínú eré.',
  'A vila venceu!': 'Abúlé ti borí!',
  'Os lobisomens venceram!': 'Àwọn ìkookò-ènìyàn ti borí!',
  'Noite {n}. A vila dorme.': 'Òru {n}. Abúlé ń sùn.',
  'Os lobisomens atacaram {nome} durante a noite.': 'Àwọn ìkookò-ènìyàn kọlu {nome} ní òru.',
  'Ninguém morreu esta noite.': 'Kò sí ẹni tó kú ní òru yìí.',
  'Dia {n}. Conversem e votem em quem vocês acham que é lobisomem.': 'Ọjọ́ {n}. Ẹ jíròrò kí ẹ sì dìbò fún ẹni tí ẹ rò pé ó jẹ́ ìkookò-ènìyàn.',
  'A vila tirou {nome} do jogo.': 'Abúlé ti yọ {nome} kúrò nínú eré.',
  'Empate: ninguém sai hoje.': 'Ọ̀mì: kò sí ẹni tó jáde lónìí.',
  'Clique em quem os lobisomens vão atacar.': 'Tẹ ẹni tí àwọn ìkookò-ènìyàn yóò kọlù.',
  'Você já usou a sua visão esta noite.': 'O ti lo ìran rẹ ti òru yìí.',
  'Clique em alguém para descobrir se é lobisomem.': 'Tẹ ẹnìkan láti mọ̀ bóyá ó jẹ́ ìkookò-ènìyàn.',
  'Clique em quem você quer proteger esta noite.': 'Tẹ ẹni tí o fẹ́ dáàbò bò ní òru yìí.',
  'Durma. Os outros papéis estão agindo.': 'Sùn. Àwọn ipa yòókù ń ṣiṣẹ́.',
  'Você saiu do jogo. Agora só assiste — sem contar nada!': 'O ti jáde nínú eré. Báyìí, wò nìkan — má sọ nǹkankan!',
  'Clique em quem você quer tirar do jogo. O mais votado sai; empate, ninguém.': 'Tẹ ẹni tí o fẹ́ yọ kúrò nínú eré. Ẹni tó ní ìbò jù ló máa jáde; tí ọ̀mì bá wà, kò sí ẹnìkan.',
  'é lobisomem': 'jẹ́ ìkookò-ènìyàn',
  'não é lobisomem': 'kì í ṣe ìkookò-ènìyàn',
  'Ninguém hoje': 'Kò sí ẹnìkan lónìí',
  'A solução do problema.': 'Ojútùú àdojúkọ náà.',
  'Acertou! Agora é torcer pelos outros.': 'Ó tọ̀nà! Báyìí, ṣe àtìlẹ́yìn fún àwọn yòókù.',
  'Esse não era o lance. Espere a solução.': 'Kì í ṣe ìgbésẹ̀ yẹn. Dúró de ojútùú.',
  'Você joga com as brancas. Ache o melhor lance.': 'O ń ṣeré pẹ̀lú funfun. Wá ìgbésẹ̀ tó dára jù.',
  'Você joga com as pretas. Ache o melhor lance.': 'O ń ṣeré pẹ̀lú dúdú. Wá ìgbésẹ̀ tó dára jù.',
  'Ver este problema no Lichess': 'Wo àdojúkọ yìí lórí Lichess',
  'Problema do Lichess · nota {nota}': 'Àdojúkọ Lichess · ìwọ̀n {nota}',
  'Cada um recebe um papel em segredo. À noite os lobisomens atacam; de dia a vila conversa e vota em quem tirar do jogo. Precisa de 4 pessoas ou mais.': 'Olúkúlùkù gba ipa kan ní ìkọ̀kọ̀. Ní òru, àwọn ìkookò-ènìyàn ń kọlù; ní ọ̀sán, abúlé ń jíròrò ó sì ń dìbò lórí ẹni tí yóò jáde nínú eré. Ó nílò ènìyàn mẹ́rin tàbí jù bẹ́ẹ̀ lọ.',
  'Problemas de xadrez': 'Àwọn àdojúkọ ṣẹ́ẹ̀sì',
  'Todo mundo recebe o mesmo problema do Lichess. Quem achar o lance certo mais rápido ganha o ponto extra.': 'Gbogbo ènìyàn gba àdojúkọ Lichess kan náà. Ẹni tó bá rí ìgbésẹ̀ tó tọ̀nà jù lọ́ọ̀ọ́kán ló gba àmì àfikún.',
  'Os problemas de xadrez não estão no servidor.': 'Àwọn àdojúkọ ṣẹ́ẹ̀sì kò sí lórí sẹ́fà.',
  'Este problema já acabou.': 'Àdojúkọ yìí ti parí.',
  'Lance inválido.': 'Ìgbésẹ̀ tí kò bófin mu.',
  'Solo': 'Fún ẹnìkan',
  'Coletivo': 'Fún àwùjọ',
  'Palavra secreta': 'Ọ̀rọ̀ àṣírí',
  'Todo mundo tenta adivinhar a mesma palavra de 5 letras, em 6 chutes. A sala vê as cores dos outros, mas não as letras. Quem acertar com menos chutes ganha mais pontos.': 'Gbogbo ènìyàn ń gbìyànjú láti mọ ọ̀rọ̀ olùlẹ́tà 5 kan náà, nínú ìgbìyànjú 6. O máa rí àwọ̀ àwọn yòókù, ṣùgbọ́n o kò ní rí lẹ́tà wọn. Ẹni tó bá mọ̀ ọ́n pẹ̀lú ìgbìyànjú díẹ̀ ló máa gba àmì púpọ̀.',
  'A palavra era: {palavra}': 'Ọ̀rọ̀ náà ni: {palavra}',
