  'Crie os cargos da comunidade primeiro, em Membros. Depois volte aqui para entregá-los sozinhos.': 'Ẹ kọ́kọ́ ṣẹ̀dá àwọn ipa àwùjọ ní Àwọn ọmọ ẹgbẹ́. Lẹ́yìn náà, ẹ padà wá síbí kí wọ́n lè máa pín wọn fúnra wọn.',
