  'Toda pessoa nova recebe estes cargos ao entrar na comunidade.': 'Gbogbo ẹni tuntun ló ń gba àwọn ipa wọ̀nyí nígbà tí wọ́n bá wọ àwùjọ.',
  'Cargos por reação': 'Àwọn ipa nípasẹ̀ ìfèsì',
  'O Syden publica uma mensagem no canal com um emoji para cada cargo. Quem reage ganha o cargo; quem tira a reação, perde.': 'Syden máa ń fi ìfiránṣẹ́ kan sí ìkànnì náà pẹ̀lú émọ́jì kan fún ipa kọ̀ọ̀kan. Ẹni tó bá fèsì yóò gba ipa náà; ẹni tó bá yọ ìfèsì rẹ̀ kúrò yóò pàdánù rẹ̀.',
