  'O arquivo': 'Fáìlì',
  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}» ({onde}) ti kúrò lórí Syden nítorí pé {quem} sọ pé òun ló ni ẹ̀tọ́ rẹ̀. Bí ẹ bá ní àṣẹ láti tẹ̀ ẹ́ jáde, ẹ fèsì níbí kí ẹ ṣàlàyé: a ó gbé ìdáhùn yín yẹ̀wò. Títí èyí yóò fi yé wa, yóò wà ní ìta. Àwọn òfin ṣàlàyé bí ó ṣe ń ṣiṣẹ́, ní apá 4: https://syden.chat/termos.html#direito-autoral',
