  'Quem tem o direito escreve para direitos@syden.chat dizendo o que é e onde está. Procure pelo nome, retire, e quem subiu recebe o aviso numa conversa com você, onde pode contestar.': 'Ẹni tó ni ẹ̀tọ́ yóò kọ̀wé sí direitos@syden.chat láti sọ ohun tó jẹ́ àti ibi tó wà. Ẹ wá a pẹ̀lú orúkọ, ẹ yọ ọ́ kúrò, ẹni tó gbé e sókè yóò sì gba ìkìlọ̀ nínú ìbánisọ̀rọ̀ pẹ̀lú yín, níbi tí wọ́n ti lè takò ó.',
