  'Desfazer o banimento': 'Mú ìfòfindè kúrò',
  'Desligar a conta de {nome}? De 13 a 15 anos, ela fica parada até ser ligada de novo.': 'Ṣé kí o tú àkáǹtì {nome}? Láti ọdún 13 sí 15, yóò dúró títí tí a ó fi tún un so.',
