  'Ligue a sua conta a um responsável até {data}, em Configurações → Família.': 'So àkáǹtì rẹ mọ́ alágbàtọ́ kan ṣáájú {data}, ní Ètò → Ìdílé.',
  'Limite de uso por dia (minutos; vazio é sem limite)': 'Ààlà lílò lójoojúmọ́ (ìṣẹ́jú; òfo túmọ̀ sí kò sí ààlà)',
  'Limite inválido: de 15 minutos a 24 horas.': 'Ààlà kò tọ́: láti ìṣẹ́jú 15 sí wákàtí 24.',
  'Mande este código para o seu pai, mãe ou responsável.': 'Fi kóòdù yìí ránṣẹ́ sí bàbá, ìyá tàbí alágbàtọ́ rẹ.',
