  'Escreva o começo do nome e escolha da lista.': 'Ẹ kọ ìbẹ̀rẹ̀ orúkọ, kí ẹ sì yan nínú àkọsílẹ̀.',
  'Seu chute': 'Àmòro yín',
  'Chutes: {n}': 'Àmòro: {n}',
  'Monstros de fantasia': 'Àwọn abàmì ẹ̀dá àròsọ',
  'Sai um monstro secreto, e cada um chuta outros da lista. Cada chute mostra o que bate com o secreto: tipo, tamanho, nível, alinhamento e como ele se desloca. Quem acertar com menos chutes ganha mais pontos.': 'Abàmì ẹ̀dá àṣírí kan yóò jáde, gbogbo èèyàn yóò sì máa mòro àwọn mìíràn nínú àkọsílẹ̀. Àmòro kọ̀ọ̀kan ń fi ohun tó bá ti àṣírí náà mu hàn: irú, ìwọ̀n, ìpele, ìwà àti bí ó ṣe ń rìn. Ẹni tó bá rí i pẹ̀lú àmòro díẹ̀ jù ló máa gba àmì púpọ̀ jù.',
  'Sai uma figura secreta da mitologia, e cada um chuta outras. Cada chute mostra o que bate com a secreta: a mitologia, o tipo, a forma e o que ela governa. Quem acertar com menos chutes ganha mais pontos.': 'Ẹ̀dá àṣírí kan láti inú ìtàn àtijọ́ yóò jáde, gbogbo èèyàn yóò sì máa mòro àwọn mìíràn. Àmòro kọ̀ọ̀kan ń fi ohun tó bá ti àṣírí náà mu hàn: ìtàn àtijọ́, irú, ìrísí àti ohun tó ń ṣàkóso. Ẹni tó bá rí i pẹ̀lú àmòro díẹ̀ jù ló máa gba àmì púpọ̀ jù.',
  'Países': 'Àwọn orílẹ̀-èdè',
  'Sai um país secreto, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a sub-região e a população. Quem acertar com menos chutes ganha mais pontos.': 'Orílẹ̀-èdè àṣírí kan yóò jáde, gbogbo èèyàn yóò sì máa mòro àwọn mìíràn. Àmòro kọ̀ọ̀kan ń fi ìjìnnà àti ìhà sí orílẹ̀-èdè àṣírí náà hàn, pẹ̀lú agbègbè, agbègbè kékeré àti iye ènìyàn. Ẹni tó bá rí i pẹ̀lú àmòro díẹ̀ jù ló máa gba àmì púpọ̀ jù.',
  'Apagar conversa': 'Pa ìjíròrò rẹ́',
  'A conversa sai da sua lista e as mensagens somem só para você. As outras pessoas continuam vendo tudo, e uma mensagem nova traz a conversa de volta.': 'Ìjíròrò náà yóò kúrò nínú àkójọ rẹ, àwọn ìfiránṣẹ́ yóò sì pòórá fún ìwọ nìkan. Àwọn yòókù yóò máa rí gbogbo rẹ̀, ìfiránṣẹ́ tuntun yóò sì mú ìjíròrò náà padà.',
