  'Escolha a resposta certa antes que o tempo acabe.': 'Yan ìdáhùn tó tọ́ kí àkókò tó tán.',
  'Balsa a dois': 'Àgbélébùú Ọkọ̀ Oníméjì',
  'Cada um rema de um lado: a remada empurra a balsa para o outro. Juntos, ela vai para a frente. Peguem as cenouras!': 'Ẹnìkọ̀ọ̀kan ń wa àjẹ̀ ní ẹ̀gbẹ́ kan: wíwa àjẹ̀ ń ti ọkọ̀ sí ẹ̀gbẹ́ kejì. Papọ̀, ó ń lọ síwájú. Ẹ kó kárọ́ọ̀tì!',
  'Retrato do coelho': 'Àwòrán Ehoro',
  'Pare cada faixa com o retrato no lugar, de cima para baixo.': 'Dá ìlà kọ̀ọ̀kan dúró nígbà tí àwòrán bá wà ní ààyè rẹ̀, láti òkè sí ìsàlẹ̀.',
  'Revezamento do riacho': 'Eré Ìfijiṣẹ́ Odò Kékeré',
  'Reme alternando ◀ e ▶ quando o remo estiver com você.': 'Wa àjẹ̀ ní pípààrọ̀ ◀ àti ▶ nígbà tí àjẹ̀ bá wà lọ́wọ́ rẹ.',
  'Fuga do rio': 'Sísá Kúrò Lódò',
  'Aperte sem parar para nadar. Quando vier um tronco, mergulhe!': 'Tẹ̀ láìdúró láti lúwẹ̀ẹ́. Tí igi bá ń bọ̀, rì sínú omi!',
  'Roda da feira': 'Kẹ̀kẹ́ Ọjà',
  'Aperte para a roda frear. Ela sempre desliza um pouco antes de parar.': 'Tẹ̀ láti dá kẹ̀kẹ́ dúró. Ó máa ń yọ̀ díẹ̀ kí ó tó dúró.',
  'Uma tacada só': 'Ìlù Kan Ṣoṣo',
  'Prenda a mira, depois a força. Quem parar mais perto da toca ganha.': 'Fi ìfojúsùn sí ààyè, lẹ́yìn náà agbára. Ẹni tó dúró súnmọ́ ihò jù ló borí.',
  'Tambor da turma': 'Ìlù Ẹgbẹ́',
  'Ouça, repita a batida no mesmo ritmo e acrescente uma no fim.': 'Fetí sí i, tún ìlù náà ṣe ní ìlù kan náà kí o sì fi ọ̀kan kún un ní ìparí.',
  'Torta de cenoura': 'Páì Kárọ́ọ̀tì',
  'Coma a torta com a sua dupla, alternando ◀ e ▶. Quem acabar primeiro ganha!': 'Jẹ páì pẹ̀lú alábàáṣiṣẹ́ rẹ, ní pípààrọ̀ ◀ àti ▶. Ẹni tó kọ́kọ́ parí ló borí!',
  'Trinca da horta': 'Mẹ́ta Ọgbà',
  'Pare os três rolos na mesma figura. Cada trinca vale um ponto.': 'Dá àwọn kẹ̀kẹ́ mẹ́ta dúró sórí àwòrán kan náà. Mẹ́ta kọ̀ọ̀kan jẹ́ àmì kan.',
  'Vidas': 'Ẹ̀mí',
  'Cenoura teleguiada': 'Kárọ́ọ̀tì Onítọ́sọ́nà',
  'Pronta': 'Ó ti ṣetán',
  'No ar': 'Ní òfurufú',
  'Frear': 'Bíréèkì',
  'Caiu! Agora é torcer de longe.': 'O ti ṣubú! Báyìí, ìgbaniníyànjú láti ọ̀nà jíjìn ni.',
  'Segure e solte: cenoura teleguiada': 'Dì í mú kí o sì tú u sílẹ̀: kárọ́ọ̀tì onítọ́sọ́nà',
  'Dois acertos você aguenta; o terceiro derruba. Curva fechada perto da cerca protege por um instante.': 'Ìlù méjì ni o lè fara dà; ìkẹta ń wó ọ lulẹ̀. Yíyí tóóró nítòsí ọgbà-ẹ̀ṣọ́ ń dáàbò bò ọ́ fún ìgbà díẹ̀.',
  'Acertos: {n}': 'Ìlù: {n}',
  'Pilotar (para trás, freia e dá ré)': 'Wakọ̀ (sẹ́yìn: bíréèkì àti padà sẹ́yìn)',
  'O barco desliza: tire o pé antes da curva. As argolas laranja dão um empurrão.': 'Ọkọ̀ ojú-omi ń yọ̀: dín ìyára kù kí o tó dé kọ̀ọ̀rọ̀. Àwọn òrùka ọsàn ń fún ni ní títì.',
  'A toupeira-rei caiu!': 'Ọba Òkété ti ṣubú!',
  'A turma caiu.': 'Ẹgbẹ́ ti ṣubú.',
  'Dano da turma: {n}': 'Ìbàjẹ́ ẹgbẹ́: {n}',
  'Sem vidas: agora é torcer pela turma.': 'Kò sí ẹ̀mí mọ́: báyìí, ìgbaniníyànjú fún ẹgbẹ́ ni.',
  'Fase {n} de {total}': 'Ìpele {n} nínú {total}',
  'Torrão na mão!': 'Ẹ̀gbin ilẹ̀ wà lọ́wọ́!',
  'Bomba de semente pronta': 'Bọ́ǹbù irúgbìn ti ṣetán',
  'Atirar o torrão': 'Ju ẹ̀gbin ilẹ̀',
  'Bomba de semente': 'Bọ́ǹbù irúgbìn',
  'Fuja das marcas no chão. Passe por cima de um torrão azulado para pegá-lo e atire de volta na toupeira; a bomba de semente é uma por fase.': 'Sá fún àwọn àmì orí ilẹ̀. Kọjá lórí ẹ̀gbin ilẹ̀ aláwọ̀ búlúù láti mú un kí o sì jù ú padà sí òkété; bọ́ǹbù irúgbìn jẹ́ ọ̀kan ní ìpele kọ̀ọ̀kan.',
  'Suba até o cata-vento. O que cai e os corvos levam de volta ao último andar.': 'Gùn títí dé ẹ̀rọ-ìtọ́ka afẹ́fẹ́. Ìṣubú àti àwọn ẹyẹ ìwò ń dá ọ padà sí àjà tó kẹ́yìn.',
  'Subir contra': 'Gùn lòdì sí',
  'Nenhum amigo subiu esta torre ainda.': 'Kò sí ọ̀rẹ́ kankan tó tíì gun ilé-gogoro yìí.',
  'Escolher a torre': 'Yan ilé-gogoro',
  'Esta subida já tinha começado quando você abriu: você assiste.': 'Gígùn yìí ti bẹ̀rẹ̀ nígbà tí o ṣí i: ò ń wò ó.',
  'Suba o celeiro por tábuas, fardos e vigas que se mexem até o cata-vento lá no alto, desviando das ferramentas que caem e dos corvos. No Solo, contra o relógio e os fantasmas dos amigos.': 'Gun abà lórí pákó, ìdì koríko àti igi àjà tó ń rìn títí dé ẹ̀rọ-ìtọ́ka afẹ́fẹ́ lókè, kí o sì yẹra fún irinṣẹ́ tó ń jábọ́ àti àwọn ẹyẹ ìwò. Fún ẹnìkan: lòdì sí aago àti iwin àwọn ọ̀rẹ́.',
  'Coelhos em teco-tecos sobre a horta, atirando ervilhas e uma cenoura teleguiada de cada vez. Dois acertos dá para aguentar; o terceiro derruba. O último no ar ganha.': 'Àwọn ehoro nínú ọkọ̀ òfurufú kékeré lórí ọgbà, tí wọ́n ń yìn ẹ̀wà àti kárọ́ọ̀tì onítọ́sọ́nà kan lẹ́ẹ̀kan. Ìlù méjì ṣeé fara dà; ìkẹta ń wó ni lulẹ̀. Ẹni ìkẹyìn ní òfurufú ló borí.',
  'A turma inteira contra a toupeira-rei, que sai das tocas em três fases. Fuja das marcas no chão, pegue os torrões azulados e atire de volta. Ganha a turma, ou ninguém.': 'Gbogbo ẹgbẹ́ lòdì sí Ọba Òkété, tó ń jáde láti inú ihò ní ìpele mẹ́ta. Sá fún àwọn àmì orí ilẹ̀, mú ẹ̀gbin ilẹ̀ aláwọ̀ búlúù kí o sì jù wọ́n padà. Ẹgbẹ́ ló borí, tàbí kò sí ẹnìkan.',
  'Corrida de barquinhos no lago, no riacho e no mangue. A água desliza: tire o pé antes da curva, cuidado com a margem e aproveite a correnteza e as argolas. No Solo, contra o relógio e os fantasmas dos amigos.': 'Ìdíje ọkọ̀ ojú-omi kékeré lórí adágún, odò kékeré àti igbó ẹrẹ̀. Omi ń yọ̀: dín ìyára kù kí o tó dé kọ̀ọ̀rọ̀, ṣọ́ra fún etí omi kí o sì lo ìṣàn omi àti àwọn òrùka. Fún ẹnìkan: lòdì sí aago àti iwin àwọn ọ̀rẹ́.',
