  'Pegue as caixas e estoure os balões dos outros. Quem fica sem balão sai.': 'Kó àwọn àpótí kí o sì fọ́ bàlúù àwọn yòókù. Ẹni tí bàlúù rẹ̀ tán yóò jáde.',
