  'Turbo (da segunda volta em diante)': 'Turbo (láti ìyípo kejì lọ)',
  '{n} voltas': 'Ìyípo: {n}',
  'A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega.': 'Agbára ni ẹ̀mí àti turbo: kíkọlu etí ń ná an, ìlà pínkì ń tún un kún.',
  'A nave explodiu: a energia acabou.': 'Ọkọ̀ náà bú: agbára ti tán.',
  'Posição: {posicao} de {total}': 'Ipò: {posicao} nínú {total}',
  'Escolher a pista': 'Yan ọ̀nà',
  'Corrida de naves-cenoura numa pista suspensa, muito mais rápida que o kart. A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega, e sair da pista é cair. No Solo, contra o relógio e os fantasmas dos amigos.': 'Ìdíje ọkọ̀ kárọ́ọ̀tì lórí ọ̀nà tí a so kọ́, tó yára ju kart lọ púpọ̀. Agbára ni ẹ̀mí àti turbo: kíkọlu etí ń ná an, ìlà pínkì ń tún un kún, jíjáde kúrò lójú ọ̀nà sì túmọ̀ sí jíjábọ́. Fún ẹnìkan: lòdì sí aago àti àwọn iwin ọ̀rẹ́ rẹ.',
  'Os karts numa arena fechada, cada um com três balões. Pegue as caixas e use os itens para estourar os balões dos outros: quem fica sem balão sai, e ganha quem sobrar.': 'Àwọn kart nínú pápá tí a tì, ọ̀kọ̀ọ̀kan pẹ̀lú bàlúù mẹ́ta. Kó àwọn àpótí kí o sì lo àwọn ohun èlò láti fọ́ bàlúù àwọn yòókù: ẹni tí bàlúù rẹ̀ tán yóò jáde, ẹni tó bá kù kẹ́yìn ló borí.',
  'Esquadrilha da toca': 'Ẹgbẹ́ Ọkọ̀ Òfurufú Ihò',
  'Aviõezinhos de cenoura contra a praga da horta: desvie das sementes, pegue os reforços e derrube o espantalho mecânico no fim. A turma voa as mesmas ondas, e a esquadrilha soma os pontos.': 'Ọkọ̀ òfurufú kéréje karọ́ọ̀tì lòdì sí kòkòrò oko ẹ̀fọ́: yẹra fún irúgbìn, kó àwọn ìrànlọ́wọ́, kí o sì wó ère ìdẹ́rùbà ẹyẹ ẹ̀rọ lulẹ̀ ní ìparí. Ẹgbẹ́ ń fò ní ìgbì kan náà, a sì ń ṣe àròpọ̀ àmì ẹgbẹ́ ọkọ̀ òfurufú.',
  'O espantalho caiu!': 'Ère ìdẹ́rùbà ẹyẹ ti ṣubú!',
  'A praga venceu desta vez.': 'Kòkòrò borí lọ́tẹ̀ yìí.',
