  'Nada em destaque ainda.': 'Kò sí ohun tí a ṣàfihàn síbẹ̀.',
  'Escolha pela estrela o que fica em destaque. É o que quem visita o seu quarto vê.': 'Fi ìràwọ̀ yan ohun tí a ó ṣàfihàn. Ohun tí àwọn tó ṣèbẹ̀wò sí yàrá rẹ ń rí nìyẹn.',
