  'Este quarto não está aberto para visita.': 'Yàrá yìí kò ṣí sílẹ̀ fún àbẹ̀wò.',
  '{quem} chama você para visitar o quarto': '{quem} ń pè ọ́ láti ṣèbẹ̀wò sí yàrá',
  'Convite para o quarto': 'Ìpè sí yàrá',
  'Corrida inválida.': 'Eré-ìje tí kò tọ́.',
  'Muitas corridas seguidas. Tente de novo daqui a pouco.': 'Eré-ìje ti pọ̀ jù lẹ́sẹẹsẹ. Gbìyànjú lẹ́ẹ̀kan sí i láìpẹ́.',
  'A corrida não está andando.': 'Eré-ìje náà kò ń lọ lọ́wọ́.',
  'Você não está nesta corrida.': 'O kò sí nínú eré-ìje yìí.',
  'Pista desconhecida.': 'Ọ̀nà eré-ìje tí a kò mọ̀.',
  'Fantasma não encontrado.': 'A kò rí iwin náà.',
