  'Convide alguém da sua lista de amigos.': 'Pe ẹnìkan láti inú àkójọ àwọn ọ̀rẹ́ rẹ.',
  'Antes dos 18, o quarto abre só para amigos e convidados.': 'Kí ọjọ́ orí tó pé 18, yàrá náà ń ṣí sí àwọn ọ̀rẹ́ àti àwọn tí a pè nìkan.',
  'Escolha até 6 para o destaque.': 'Yan tó 6 láti fi hàn ní pàtàkì.',
