  'Menos de duas pessoas ficaram até o fim: desta vez, sem pódio.': 'Ènìyàn tí kò tó méjì ló dúró dé òpin: ní àkókò yìí, kò sí pẹpẹ ẹ̀yẹ.',
  'Esta fase já tinha começado quando você abriu: você assiste.': 'Ìpele yìí ti bẹ̀rẹ̀ kí o tó ṣí i: o ń wò ó.',
