  'Venda os prédios do grupo antes de trocar.': 'Ta àwọn ilé inú ẹgbẹ́ náà kí o tó ṣe pàṣípààrọ̀.',
  'Essa cidade não é sua.': 'Ìlú yìí kì í ṣe tìrẹ.',
  'Só se constrói em cidade.': 'Inú ìlú nìkan ni a ti ń kọ́lé.',
  'Para construir, é preciso ter todas as cidades do grupo.': 'Láti kọ́lé, o gbọ́dọ̀ ní gbogbo ìlú inú ẹgbẹ́ náà.',
  'Resgate as cidades hipotecadas do grupo antes de construir.': 'Ra àwọn ìlú ẹgbẹ́ náà tí a fi dógò padà kí o tó kọ́lé.',
