  'Essa cidade não tem prédio.': 'Ìlú yìí kò ní ilé.',
  'Essa cidade já está hipotecada.': 'A ti fi ìlú yìí dógò tẹ́lẹ̀.',
  'Venda os prédios do grupo antes de hipotecar.': 'Ta àwọn ilé inú ẹgbẹ́ náà kí o tó fi dógò.',
