  'Feriado': 'Ọjọ́ ìsinmi',
  'Sua quadrilha ganhou o festival junino: receba {valor}.': 'Ẹgbẹ́ ijó rẹ borí níbi àjọ̀dún oṣù Kẹfà: gba {valor}.',
  'Achou dinheiro no bolso da calça: receba {valor}.': 'O rí owó nínú àpò ṣòkòtò: gba {valor}.',
  'Vendeu tudo na feira: receba {valor}.': 'O ta gbogbo ẹrù ní ọjà: gba {valor}.',
  'O carro quebrou na estrada: pague {valor}.': 'Ọkọ̀ bàjẹ́ lójú ọ̀nà: san {valor}.',
  'Multa por parar na calçada: pague {valor}.': 'Owó ìtanràn fún dídúró sí ọ̀nà àwọn ẹlẹ́sẹ̀: san {valor}.',
  'Volte para a Largada e receba o salário.': 'Padà sí Ìbẹ̀rẹ̀ kí o gba owó oṣù.',
  'Pegou uma carona: avance 3 casas.': 'Ẹnì kan gbé ọ lọ́fẹ̀ẹ́: tẹ̀síwájú àpótí 3.',
  'Pegou o ônibus errado: volte 3 casas.': 'O wọ bọ́ọ̀sì tí kò tọ́: padà sẹ́yìn àpótí 3.',
  'A chuva fechou a estrada: vá para o Engarrafamento.': 'Òjò ti dí ọ̀nà: lọ sí Súnkẹrẹ-fàkẹrẹ.',
  'Reforma geral: pague {valor} por prédio.': 'Àtúnṣe gbogbogbò: san {valor} fún ilé kọ̀ọ̀kan.',
  'É o seu aniversário: cada um te dá {valor}.': 'Ọjọ́ ìbí rẹ ni: ẹnì kọ̀ọ̀kan fún ọ ní {valor}.',
  'Você pagou a festa: dê {valor} a cada um.': 'Ìwọ lo san owó àsè: fún ẹnì kọ̀ọ̀kan ní {valor}.',
  'Ganhou uma passagem: avance até o próximo transporte.': 'O rí tíkẹ́ẹ̀tì gbà: tẹ̀síwájú dé ọkọ̀ ìrìnnà tó kàn.',
  '{nome} passou pela Largada: +{valor}.': '{nome} kọjá Ìbẹ̀rẹ̀: +{valor}.',
  '{nome} pagou {valor} de aluguel a {outro} ({cidade}).': '{nome} san {valor} owó ilé fún {outro} ({cidade}).',
  '{nome} comprou {cidade} por {valor}.': '{nome} ra {cidade} ní {valor}.',
  'Ninguém deu lance: {cidade} continua à venda.': 'Kò sí ẹni tó lu owó: {cidade} ṣì wà fún títà.',
  '{nome} levou {cidade} no leilão por {valor}.': '{nome} gba {cidade} níbi gbànjo ní {valor}.',
  '{nome} pagou {valor} de pedágio.': '{nome} san {valor} owó ibodè.',
  '{nome} ficou no engarrafamento e perde a próxima vez.': '{nome} há sínú súnkẹrẹ-fàkẹrẹ, yóò sì pàdánù ìgbà tó kàn.',
