  '{nome} faliu e as cidades voltaram ao banco.': 'Owó {nome} ti tán, àwọn ìlú sì padà sí báńkì.',
  '{nome} faliu, e tudo o que tinha foi para {outro}.': 'Owó {nome} ti tán, gbogbo ohun tó ní sì lọ sọ́dọ̀ {outro}.',
  '{nome} e {outro} fecharam uma troca.': '{nome} àti {outro} ṣe pàṣípààrọ̀.',
