  'rodadas': 'ìpele',
  'Até sobrar um': 'Títí ẹnì kan yóò fi kù',
  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'Rìn kiri àwọn olú-ìlú Bàràsílì, ra àwọn ìlú kí o sì gba owó ilé lọ́wọ́ àwọn tó bá dúró sí wọn. Tí o bá ní gbogbo agbègbè kan, o lè kọ́ ilé. Ṣe pàṣípààrọ̀, figagbága níbi gbànjo, má sì jẹ́ kí owó tán lọ́wọ́ rẹ.',
