  'Contorno': 'Ìlà etí',
  'O fundo não é de uma cor só, e ficou como veio.': 'Ẹ̀yìn kì í ṣe àwọ̀ kan ṣoṣo, nítorí náà a fi sílẹ̀ bí ó ṣe wà.',
  'No app do Syden, o recorte funciona com qualquer fundo.': 'Nínú áàpù Syden, a lè yọ ẹ̀yìn èyíkéyìí kúrò.',
  'O recorte com o modelo falhou, e ficou o recorte simples.': 'Yíyọ pẹ̀lú àwòṣe kò ṣiṣẹ́, nítorí náà a lo ọ̀nà tí ó rọrùn.',
  'Mandar figurinha': 'Fi sítíkà ránṣẹ́',
  'Tirar figurinha': 'Yọ sítíkà kúrò',
  'Crie figurinhas com as suas imagens, ou salve as que receber numa conversa.': 'Ṣẹ̀dá sítíkà pẹ̀lú àwọn àwòrán rẹ, tàbí fi àwọn tí o gbà nínú ìbánisọ̀rọ̀ pamọ́.',
  'Dominó': 'Dómínò',
  'Truco': 'Truco',
  'Damas': 'Dáàmù',
  'Batalha naval': 'Ogun ojú omi',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'Dómínò bí ti àtẹ̀yìnwá, fún ènìyàn 2 sí 4 (bí wọ́n bá jẹ́ 4, ní méjì-méjì). So àwọn òkúta pọ̀ ní àwọn ìpẹ̀kun, ẹni tó bá kọ́kọ́ parí yóò gba àmì ọwọ́ àwọn yòókù.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'Truco ti Brazil, pẹ̀lú káàdì tí a ṣí àti manilha, fún ènìyàn 2 tàbí méjì-méjì nínú 4. Béèrè truco, gbé e sí mẹ́fà, mẹ́sàn-án àti méjìlá, tàbí sá. Ẹni tó bá ní àmì 12 ló borí.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'Dáàmù ti Brazil: jíjẹ jẹ́ dandan, síwájú àti sẹ́yìn, ọba sì ń rìn gbogbo ìlà ìdábùú. Yàrá ń wò.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'Ẹnì kọ̀ọ̀kan fi ọkọ̀ ojú omi rẹ̀ pamọ́, ó sì ń yìnbọn sí òkun ẹnì kejì. Bí o bá bà á, yìnbọn lẹ́ẹ̀kan sí i. Ẹni tó bá kọ́kọ́ rì gbogbo ọkọ̀ ló borí. Yàrá ń wò.',
