  Xadrez: 'Ayò chess',
  'Uma partida de xadrez inteira, com todas as regras. Quem abre fica com as brancas. A sala assiste.': 'Ere chess pípé, pẹ̀lú gbogbo òfin. Ẹni tó bẹ̀rẹ̀ ló ń fi funfun ṣeré. Iyàrá ń wò ó.',
  'Xeque!': 'Chẹ́ẹ̀kì!',
  Dama: 'Ayaba',
  Torre: 'Ilé-gogoro',
  Bispo: 'Bíṣọ́ọ̀bù',
  'Cozinha da toca': 'Ilé ìdáná ihò',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': 'Mú àwọn èròjà láti inú àpótí, gé wọn lórí pákó, sè wọ́n lórí ààrò àti nínú ààrò ìyàn láì jẹ́ kí wọ́n jóná, tò wọ́n sínú àwo kí o sì fi wọ́n lé ní fèrèsé. Gbogbo ènìyàn ló ń gba àṣẹ kan náà: ẹni tó bá fi àwo tó pọ̀ jù lé láàárín ìṣẹ́jú 3 ló borí.',
  'Pegar ou largar': 'Gbé tàbí gbé kalẹ̀',
  'Este jogo precisa de gráficos 3D, que não abriram neste aparelho.': 'Eré yìí nílò àwòrán 3D, tí kò ṣí lórí ẹ̀rọ yìí.',
  'Este prato não é o pedido.': 'Àwo yìí kì í ṣe àṣẹ náà.',
  Kickflip: 'Kickflip',
  Grab: 'Grab',
  Manual: 'Manual',
  'Rolê do coelho': 'Ìrìn ehoro',
  'Um minuto na pista de skate. Pule, gire, faça grind nos corrimãos e emende as manobras num combo: cada manobra a mais multiplica os pontos, mas cair perde o combo inteiro.': 'Ìṣẹ́jú kan ní pápá skate. Fò, yí, ṣe grind lórí irin ẹ̀gbẹ́ kí o sì so àwọn ọgbọ́n pọ̀ sínú combo: ọgbọ́n àfikún kọ̀ọ̀kan ń sọ àmì di púpọ̀, ṣùgbọ́n ìṣubú ń pàdánù gbogbo combo.',
  Pausar: 'Dánudúró',
  'Caiu!': 'Ó ṣubú!',
  'Melhor combo: {n}': 'Combo tó dára jù: {n}',
  'Trânsito da toca': 'Ọkọ̀ Ojú-ọ̀nà Ihò',
  'Um minuto para soltar os carros do cruzamento sem deixar que batam. Fila cheia também custa pontos.': 'Ìṣẹ́jú kan láti jẹ́ kí àwọn mọ́tò kọjá ní oríta láìjẹ́ kí wọ́n kọlu ara wọn. Ìlà tó kún náà ń dín àmì kù.',
  Liberar: 'Jẹ́ kó lọ',
  'Carrinhos da toca': 'Ọkọ̀ Ìṣeré Ihò',
  'Uma pista de carrinhos de brinquedo com quatro faixas: o carro segue a faixa sozinho, e você só acelera. Acelerou demais na curva, ele sai voando e perde tempo. No Solo, contra o relógio, os fantasmas dos amigos e robôs.': 'Ọ̀nà ọkọ̀ ìṣeré olójú ọ̀nà mẹ́rin: ọkọ̀ náà ń tẹ̀lé ojú ọ̀nà rẹ̀ fúnra rẹ̀, ìwọ kàn ń mú un yára sí i. Tí o bá mú un yára jù ní ibi títẹ̀, yóò fò jáde kúrò ní ọ̀nà, yóò sì pàdánù àkókò. Fún ẹnìkan: láti borí aago, àwọn iwin àwọn ọ̀rẹ́ àti àwọn rọ́bọ́ọ̀tì.',
  'Acelerar': 'Mú yára',
  'Saiu da pista!': 'Ó ti jáde kúrò ní ọ̀nà!',
  'Saídas da pista: {n}': 'Jíjáde kúrò ní ọ̀nà: {n}',
  'Segure para acelerar e solte antes da curva: quando o carro treme, ele está no limite.': 'Tẹ̀ ẹ́ mọ́lẹ̀ láti mú yára, kí o sì fi sílẹ̀ ṣáájú ibi títẹ̀: nígbà tí ọkọ̀ bá ń mì, ó ti dé ààlà.',
  // O cômodo do quarto: a planta e as cores da parede e do piso (06/11/2026)
