  // Saúde do servidor: ações da Hetzner e diagnóstico do host
  "Diagnóstico do host": "Àyẹ̀wò olùgbàlejò",
  "Registros limitados de Docker, SSH, logind e kernel dos três boots mais recentes. Podem conter endereços IP.": "Àkọsílẹ̀ díẹ̀ ti Docker, SSH, logind àti kernel láti ìbẹ̀rẹ̀ mẹ́ta tó kẹ́yìn. Ó lè ní àdírẹ́sì IP.",
  "Atualizar diagnóstico": "Sọ àyẹ̀wò di tuntun",
  "Ainda não há snapshot. Ele será coletado na próxima abertura do cofre.": "Kò sí àwòrán ìpo síbẹ̀. A ó kó o jọ nígbà tí a bá ṣí àpótí ìpamọ́ lẹ́ẹ̀kan sí i.",
  "Coletado em {data}": "A kó jọ ní {data}",
  "Medido pela {nome}": "{nome} ló wọ̀n ọ́n",
  "Os mesmos números do painel do provedor. Inclui o disco, que o servidor não mede sozinho.": "Àwọn nọ́ńbà kan náà bí ti dáṣíbọ́ọ̀dù olùpèsè. Ó ní díìsìkì, tí sáfà kò wọ̀n fúnra rẹ̀.",
  "Ações no servidor": "Àwọn ìgbésẹ̀ lórí sáfà",
  "O histórico da Hetzner: ligar, desligar e reiniciar, pelo painel ou pela API. Uma queda sem ação aqui não foi comandada por esses caminhos.": "Ìtàn Hetzner: títan, pípa àti títún bẹ̀rẹ̀, láti dáṣíbọ́ọ̀dù tàbí API. Ìdádúró tí kò ní ìgbésẹ̀ níbí kò wá láti àwọn ọ̀nà wọ̀nyí.",
  "Nenhuma ação registrada.": "Kò sí ìgbésẹ̀ tí a kọ sílẹ̀.",
  "Ligar o servidor": "Tan sáfà",
  "Desligar o servidor": "Pa sáfà",
  "Reiniciar o servidor": "Tún sáfà bẹ̀rẹ̀",
  "Concluída": "Ó ti parí",
  "Falhou": "Kò ṣeé ṣe",
  "Em andamento": "Ó ń lọ lọ́wọ́",
  // O servidor fora do ar
  "503 — O servidor do Syden não está respondendo": "503 — Sáfà Syden kò dáhùn",
  "O Syden está fora do ar": "Syden kò ṣiṣẹ́",
  "Não é a sua internet: o nosso servidor parou de responder. Quando ele voltar, esta tela some sozinha.": "Kì í ṣe íńtánẹ́ẹ̀tì rẹ: sáfà wa ti dẹ́kun láti dáhùn. Nígbà tó bá padà, ojú-ìbòjú yìí yóò pòórá fúnra rẹ̀.",
  "OFFLINE — Sem conexão com a internet": "OFFLINE — Kò sí ìsopọ̀ íńtánẹ́ẹ̀tì",
  "Sem internet": "Kò sí íńtánẹ́ẹ̀tì",
  "Quando a conexão voltar, esta tela some sozinha.": "Nígbà tí ìsopọ̀ bá padà, ojú-ìbòjú yìí yóò pòórá fúnra rẹ̀.",
  // O palco: esconder a faixa de baixo
