  // A caminha do gato
  "Caminha do gato": "Ibùsùn ológbò",
  "Redonda e fofa, com a entrada mais baixa. O gato dorme aqui.": "Ó yíká, ó sì rọ̀, pẹ̀lú ẹnu ọ̀nà tó lọ sílẹ̀. Ológbò ń sùn níbí.",
  // O Guarda-roupa: a aba do avatar
