  'Aberto': "Ó ṣí sílẹ̀",
  'Adicionar foto': "Fi fọ́tò kún un",
  'Apagar este bolão, com os palpites?': "Pa ìdíje yìí rẹ́, pẹ̀lú àwọn àsọtẹ́lẹ̀ rẹ̀?",
  'Fecha em {quando}': "Yóò tì ní {quando}",
  'Fechado': "Ó ti tì",
  'Fechar palpites': "Ti àsọtẹ́lẹ̀",
  'Ganha quem chegar mais perto. Só pontos, sem dinheiro.': "Àsọtẹ́lẹ̀ tó sún mọ́ jùlọ ló borí. Àmì nìkan, kò sí owó.",
  'Lançar resposta': "Tẹ ìdáhùn sí i",
  'Ninguém palpitou.': "Kò sí ẹni tó sọtẹ́lẹ̀.",
  'Os palpites dos outros aparecem quando fechar.': "Àsọtẹ́lẹ̀ àwọn ẹlòmíràn yóò hàn nígbà tí ó bá tì.",
  'Palpites até (opcional)': "Àsọtẹ́lẹ̀ títí di (àṣàyàn)",
  'Qual é a pergunta?': "Kí ni ìbéèrè náà?",
  'Reabrir palpites': "Tún àsọtẹ́lẹ̀ ṣí",
  'Resposta certa': "Ìdáhùn tó tọ́",
  'Resposta: {quando}': "Ìdáhùn: {quando}",
  'Seu palpite': "Àsọtẹ́lẹ̀ rẹ",
  'Seu palpite está salvo. Dá para mudar até fechar.': "A ti fi àsọtẹ́lẹ̀ rẹ pamọ́. O lè yí i padà títí tí yóò fi tì.",
  // O fundo da câmera (16/11/2026)
  'Fundo da câmera': "Ẹ̀yìn kámẹ́rà",
  'Desfocado': "Mú kó ṣókùnkùn",
  'Desfoca, apaga ou troca o que aparece atrás de você. A imagem da câmera não sai do computador para isso.': "Ó máa ń mú ohun tí ó hàn lẹ́yìn rẹ ṣókùnkùn, pa á rẹ́ tàbí pààrọ̀ rẹ̀. Àwòrán kámẹ́rà kì í jáde kúrò nínú kọ̀mpútà rẹ fún èyí.",
  // A transmissão personalizada (16/11/2026)
  'Nativa': "Ti àbínibí",
  'Resolução': "Ìpinnu àwòrán",
  'Quadros por segundo': "Fírémù ní ìṣẹ́jú-àáyá",
  'Para quando a escolha automática errar: a resolução e os quadros ficam os que você escolher, do começo ao fim da transmissão.': "Fún ìgbà tí àṣàyàn aládàáṣe bá ṣàṣìṣe: ìpinnu àwòrán àti fírémù yóò dúró bí o ṣe yàn án, láti ìbẹ̀rẹ̀ dé òpin ìgbóhùnsáfẹ́fẹ́.",
  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "Àwọn ipa ohùn àti kámẹ́rà tí a ń ṣe lórí kọ̀mpútà rẹ, láìfi nǹkan kankan ránṣẹ́ sí sáfà.",
  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "Ẹ̀wọ̀n Ihò",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "Ẹ jọ la ihò ọba olú kọjá: àwọn yàrá tó kún fún ẹranko, àpótí tí kárọ́ọ̀tì tó ń lọ tó sì ń padà wà nínú rẹ̀, àwọn bọ́tìnnì tó nílò ènìyàn méjì lẹ́ẹ̀kan náà, àti ìlẹ̀kùn tí a ti tì. Ènìyàn 1 sí 4.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "Pápá Ìjà Ihò",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "Ẹ̀ṣẹ́ kíákíá lòdì sí alátakò mẹ́ta ti kọ̀mpútà. Ka àmì ẹ̀ṣẹ́ kọ̀ọ̀kan, yẹ̀ tàbí dáàbò bo ara rẹ, kí o sì lù ú níbi tó ṣí sílẹ̀. Lílù nígbà tí ìbọ̀wọ́ bá ń dán ń kún ìràwọ̀ ẹ̀ṣẹ́ alágbára.",
  'Esquivar': "Yẹ̀",
  'Abaixar e defender': "Bẹ̀rẹ̀ kí o dáàbò bo",
  'Socar': "Gbá ẹ̀ṣẹ́",
  'Soco forte': "Ẹ̀ṣẹ́ alágbára",
  'Aperte os socos para levantar!': "Tẹ àwọn bọ́tìnnì ẹ̀ṣẹ́ kí o lè dìde!",
  'Lutas vencidas: {n}': "Ìjà tí o borí: {n}",
  'Nocaute!': "Ìlulẹ̀!",
  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "Ọ̀nà Ìràwọ̀",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "Àwọn ehoro nínú ọkọ̀ òfuurufú lórí ilẹ̀ pílánẹ́ẹ̀tì kan àti nínú òfuurufú: yìnbọn, di ìbọn mú láti tì àfojúsùn, yípo láti yí ọta padà, kí o sì yan ọ̀nà níbi oríta. Ẹgbẹ́ náà ń fò ní ọ̀nà kan náà, ọ̀gá sì ń dúró ní òpin.",
  'Pirueta': "Yíyípo",
  'Segure para travar a mira': "Di mú láti tì í",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "Kọ́mándò Kárọ́ọ̀tì",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "Sá kí o sì yìnbọn pẹ̀lú ẹgbẹ́: ìbọn kárọ́ọ̀tì ń fojú sí ọ̀nà mẹ́jọ, bọ́ǹbù ọwọ́ ń ṣí ọ̀nà, ẹni tó bá tú àwọn ọmọ ehoro tí wọ́n há sínú àgò sílẹ̀ yóò gba agbára àfikún. Dírágónì ń dúró ní òpin: ènìyàn 1 sí 4.",
  'Andar e mirar': "Rìn kí o fojú sí",
  'Granada': "Bọ́ǹbù ọwọ́",
  // O Pinball da Horta (16/11/2026)
  'Pinball da Horta': "Pinball Ọgbà",
  'Uma mesa de pinball na horta: segure a mola, rebata nos repolhos e derrube as três cenouras para acender a toca do coelho, que solta mais uma bola. Três bolas, e sacudir demais trava a mesa.': "Tábìlì pinball nínú ọgbà ẹ̀fọ́: di sípíríngì mú, jẹ́ kí bọ́ọ̀lù fò lu kábéèjì, kí o sì wó kárọ́ọ̀tì mẹ́ta lulẹ̀ láti tan ihò ehoro, tí yóò tú bọ́ọ̀lù kan sí i sílẹ̀. Bọ́ọ̀lù mẹ́ta, mímì jù yóò sì tì tábìlì pa.",
  'Palhetas': "Àwọn ìgbá",
  'Mola': "Sípíríngì",
  'Sacudir': "Mì í",
  'Bola salva!': "A gba bọ́ọ̀lù là!",
  'Multibola!': "Bọ́ọ̀lù púpọ̀!",
  'Mesa travada!': "Tábìlì ti tìpa!",
  'Cuidado!': "Ṣọ́ra!",
  'Recordes dos amigos': "Àkọsílẹ̀ àwọn ọ̀rẹ́",
