  'Desafios de voo: asa-delta, mochila a jato e paraquedas. Passe pelos anéis e pouse no alvo, perto do centro e de leve.': 'Ìpèníjà fífò: hang glider, àpò jet àti parachute. Fò gba inú àwọn òrùka kọjá kí o sì balẹ̀ sórí àfojúsùn, nítòsí àárín àti pẹ̀lẹ́pẹ̀lẹ́.',
