  // Lendas da Toca (16/11/2026)
  'Lendas da Toca': "Àlọ́ Ihò",
  'Um RPG de turnos curto: cada um controla um herói da turma. Escolham juntos, combinem ataques e vençam o dragão do castelo.': "RPG kúkúrú tí a ń ṣe ní àyè-àyè: ẹnì kọ̀ọ̀kan ń darí akọni kan nínú ẹgbẹ́. Ẹ yan papọ̀, ẹ dàpọ̀ ìkọlù, kí ẹ sì ṣẹ́gun dírágónì ààfin.",
  'Faísca': "Ìtanná",
  'Erva': "Ewéko",
  'Flecha': "Ọfà",
  'Aguenta mais e protege a turma.': "Ó ń fara da jù, ó sì ń dáàbò bo ẹgbẹ́.",
  'Acerta todos os inimigos.': "Ó ń lu gbogbo ọ̀tá.",
  'Cura a turma e levanta quem caiu.': "Ó ń wo ẹgbẹ́ sàn, ó sì ń gbé àwọn tó ṣubú dìde.",
  'Um tiro forte, que passa da defesa.': "Ìbọn alágbára tí ó ń la ààbò kọjá.",
  'Escolha o seu herói': "Yan akọni rẹ",
