  'Habilidade': "Ọgbọ́n",
  'Defender': "Dáàbò bò",
  'Combo': "Kọ́mbò",
  'Dois ou mais no Combo atacam juntos.': "Méjì tàbí jù bẹ́ẹ̀ lọ lórí Kọ́mbò ń kọlù papọ̀.",
  'Equipar': "Wọ̀",
  'Deixar': "Fi sílẹ̀",
  // Bichos da Toca (16/11/2026)
  'Bichos da Toca': "Àwọn Ẹranko Ihò",
  'Ande pelo campo, faça amizade com os bichos do mato usando uma cenoura e monte uma equipe de até seis. Vença o desafio da casa azul e, na sala, lute com a equipe de um amigo.': "Rìn kiri nínú pápá, bá àwọn ẹranko inú koríko gígùn ṣọ̀rẹ́ pẹ̀lú kárọ́ọ̀tì, kí o sì kó ẹgbẹ́ tó tó mẹ́fà jọ. Borí ìpèníjà ilé aláwọ̀ búlúù, kí o sì bá ẹgbẹ́ ọ̀rẹ́ kan jà nínú yàrá.",
