  "A mesma posição pela terceira vez empata, e 20 lances só de dama sem comer também.": "Ipò kan náà nígbà kẹta jẹ́ ọ̀mì, bẹ́ẹ̀ sì ni ìgbésẹ̀ 20 ti ọbabìnrin nìkan láìjẹ nǹkan.",
  "À noite, veja quem os lobisomens atacaram. Uma poção salva essa pessoa e outra tira alguém do jogo; cada uma vale uma vez.": "Ní òru, wo ẹni tí àwọn ìkookò-ènìyàn kọlù. Oògùn kan gba ẹni náà là, èkejì sì yọ ẹnì kan kúrò nínú eré; ọ̀kọ̀ọ̀kan wúlò lẹ́ẹ̀kan.",
  "A partida se desencontrou entre os computadores e foi encerrada.": "Ìdíje náà kò bára mu láàárín àwọn kọ̀mpútà, a sì ti parí rẹ̀.",
  "A pedra que termina o lance na última fileira vira dama, que anda a diagonal inteira.": "Òkúta tó parí ìgbésẹ̀ sí ìlà tó kẹ́yìn di ọbabìnrin, tí ń rìn gbogbo ìlà ẹ̀gbẹ́.",
