  "Toca do rei-cogumelo": "Ihò Ọba Olu",
  "Mina dos postes": "Ìwakùsà Àwọn Òpó",
  // Os mini-games e as insígnias (19/11/2026)
  "{nome} terminou uma Maravilha: defenda-a por 2 minutos!": "{nome} parí Ohun ìyanu kan: dáàbò bò ó fún ìṣẹ́jú 2!",
  "{nome} terminou uma Maravilha.": "{nome} parí Ohun ìyanu kan.",
  "A Maravilha da outra equipe ficou de pé por 2 minutos.": "Ohun ìyanu ẹgbẹ́ kejì dúró fún ìṣẹ́jú 2.",
  "A Maravilha da sua equipe ficou de pé por 2 minutos.": "Ohun ìyanu ẹgbẹ́ rẹ dúró fún ìṣẹ́jú 2.",
  "A outra equipe derrubou os dois centros da vila de vocês.": "Ẹgbẹ́ kejì wó àárín abúlé yín méjèèjì.",
  "A outra equipe desistiu.": "Ẹgbẹ́ kejì ti juwọ́ sílẹ̀.",
  "A outra equipe saiu da sala.": "Ẹgbẹ́ kejì ti kúrò nínú yàrá.",
  "A sua equipe desistiu.": "Ẹgbẹ́ rẹ ti juwọ́ sílẹ̀.",
  "A sua equipe ficou fora da sala por muito tempo.": "Ẹgbẹ́ rẹ ti pẹ́ jù ní ìta yàrá.",
  "Duas equipes de dois. Os robôs completam os lugares que faltam.": "Ẹgbẹ́ méjì tí ọ̀kọ̀ọ̀kan ní ènìyàn méjì. Àwọn rọ́bọ́ọ̀tì ń kún àyè tó kù.",
  "Gênero": "Akọ tàbí abo",
  "Levadiça": "Afárá gbígbé",
  'Nenhuma conversa ainda. Toque em alguém na lista de pessoas da comunidade e escolha "Enviar mensagem".': "Kò sí ìbánisọ̀rọ̀ kankan síbẹ̀. Ẹ fọwọ́ kan ẹnìkan nínú àkójọ àwọn ènìyàn àwùjọ, kí ẹ sì yan \"Fi ìfiránṣẹ́ ránṣẹ́\".",
  "Varia": "Ó yàtọ̀ síra",
  "Vitória de {nomes}": "Ìṣẹ́gun {nomes}",
  "Vocês derrubaram os dois centros da vila da outra equipe.": "Ẹ wó àárín abúlé méjèèjì ti ẹgbẹ́ kejì.",
  // Os mini-games e as insígnias (19/11/2026)
  "A cidade que ninguém compra vai a leilão. Hipotecar uma cidade dá dinheiro, mas ela não cobra aluguel.": "Ìlú tí ẹnikẹ́ni kò rà máa lọ sí ọjà gbanjo. Fífi ìlú dógò máa ń mówó wá, ṣùgbọ́n kò ní gba owó ilé.",
  "A dica acende a peça que move. O problema com dica não pontua; na corrida, ela tira 10 segundos.": "Ìtọ́sọ́nà máa ń tan ìmọ́lẹ̀ sí ègé tó yẹ kó gbé. Àdojúkọ tí a lo ìtọ́sọ́nà fún kì í ní àmì; nínú eré ìje, ó máa ń yọ ìṣẹ́jú-àáyá 10.",
  "A manilha é o valor seguinte ao da vira e ganha de todas. Entre elas: ouros, espadas, copas e paus, o zap.": "Manilha ni iye tó tẹ̀lé ti káàdì tí a ṣí, ó sì ń borí gbogbo wọn. Láàrin wọn: dáyámọ́ńdì, ṣọ́bìrì, ọkàn àti kọ́ọ̀bù, èyí ni zap.",
  "A última nave de cada volta sai.": "Ọkọ̀ tó kẹ́yìn ní ìyípo kọ̀ọ̀kan máa jáde.",
  "Abaixar": "Bẹ̀rẹ̀",
  "Acertos em sequência: {n}": "Àṣeyọrí lẹ́sẹẹsẹ: {n}",
  "Ande pelo dado e compre a capital onde parar. Quem para na cidade de outro paga aluguel.": "Rìn gẹ́gẹ́ bí dáìsì ṣe sọ, kí o ra olú-ìlú tí o bá dúró sí. Ẹni tó bá dúró sí ìlú ẹlòmíì máa san owó ilé.",
  "Cada linha, coluna e bloco de 3 × 3 tem os números de 1 a 9, sem repetir.": "Ìlà kọ̀ọ̀kan, òpó kọ̀ọ̀kan àti àpótí 3 × 3 kọ̀ọ̀kan ní àwọn nọ́ńbà 1 sí 9, láìtún ṣe.",
  "Cada um recebe 3 cartas. Leva a mão quem ganhar 2 das 3 rodadas.": "Kálukú gba káàdì 3. Ẹni tó bá borí ìyípo 2 nínú 3 ló gba ọwọ́ náà.",
  "Campeonato": "Ìdíje asíwájú",
  "Com 11 pontos, a dupla vê as cartas e decide se joga a mão de onze. Vence quem chegar a 12.": "Pẹ̀lú àmì 11, ẹgbẹ́ náà rí káàdì wọn, ó sì pinnu bóyá yóò ṣe ọwọ́ mọ́kànlá. Ẹni tó bá dé 12 ló borí.",
  "Com a região inteira, construa até 4 prédios: o aluguel sobe a cada um.": "Pẹ̀lú gbogbo agbègbè náà, kọ́ ilé gíga tó tó 4: owó ilé máa ń gòkè pẹ̀lú ọ̀kọ̀ọ̀kan.",
  "Com estrelas, o soco forte (★) gasta todas de uma vez e dói mais.": "Pẹ̀lú ìràwọ̀, ẹ̀ṣẹ́ alágbára (★) máa ń lo gbogbo wọn lẹ́ẹ̀kan, ó sì máa ń dunni jù.",
  "Dica": "Ìtọ́sọ́nà",
  "Dica: este problema não pontua": "Ìtọ́sọ́nà: àdojúkọ yìí kò ní àmì",
  "Dica: tira 10 segundos": "Ìtọ́sọ́nà: ó yọ ìṣẹ́jú-àáyá 10",
  "Eliminação": "Ìyọkúrò",
  "Encoste uma pedra numa ponta da mesa com o mesmo número.": "Fi òkúta kan sí òpin tábìlì tí ó ní nọ́ńbà kan náà.",
  "Escolha a casa e depois o número. O lápis anota só para você.": "Yan àpótí, lẹ́yìn náà nọ́ńbà. Pẹ́ńsùlù ń kọ fún ìwọ nìkan.",
  "Esquive do golpe e soque logo depois: é o contra-ataque, e vale estrela.": "Yẹ ẹ̀ṣẹ́ náà, kí o sì gbá a lójú ẹsẹ̀: ìyẹn ni ìkọlù padà, ó sì ń fúnni ní ìràwọ̀.",
  "Fora da corrida na volta {n}.": "Kúrò nínú eré ìje ní ìyípo {n}.",
  "Força das cartas": "Agbára àwọn káàdì",
  "Ganha o maior patrimônio no fim das rodadas, ou quem sobrar.": "Ẹni tó ní ọrọ̀ tó pọ̀ jù ní òpin àwọn ìyípo ló borí, tàbí ẹni tó kù.",
  "Iniciante": "Olùbẹ̀rẹ̀",
  "Mestre": "Ọ̀gá",
  "Na sequência, cada acerto traz um problema mais difícil, e o primeiro erro acaba.": "Nínú lẹ́sẹẹsẹ, àṣeyọrí kọ̀ọ̀kan ń mú àdojúkọ tó le jù wá, àṣìṣe àkọ́kọ́ sì ń parí rẹ̀.",
  "O número pequeno no botão diz quantos ainda faltam.": "Nọ́ńbà kékeré lórí bọ́tìnnì ń sọ iye tó ṣì kù.",
  "Os cinco traçados seguidos contra o computador, com pontos.": "Àwọn ọ̀nà márùn-ún lẹ́sẹẹsẹ lòdì sí kọ̀ǹpútà, pẹ̀lú àmì.",
  "Peça truco e a mão vale 3. Quem responde aceita, corre ou aumenta para 6, 9 ou 12.": "Béèrè truco, ọwọ́ náà á sì tó 3. Ẹni tó ń dáhùn á gbà á, á sá, tàbí á gbé e sí 6, 9 tàbí 12.",
  "Quem bate fica sem pedras e leva os pontos das mãos dos outros. Trancado, leva quem tem menos pontos na mão.": "Ẹni tó bá parí òkúta rẹ̀ máa gba àmì tó wà lọ́wọ́ àwọn yòókù. Tí eré bá dí, ẹni tó ní àmì tó kéré jù lọ́wọ́ ló gbà á.",
  "Sem pedra que sirva, compre. Sem nada para comprar, a vez passa.": "Tí kò bá sí òkúta tó bá a mu, ra. Tí kò bá sí nǹkan láti rà, àyè rẹ kọjá.",
  "Sequência": "Lẹ́sẹẹsẹ",
  "Soque quando a luva brilhar: o golpe para e você ganha uma estrela.": "Gbá ẹ̀ṣẹ́ nígbà tí ìbọ̀wọ́ bá ń tàn: ìkọlù náà á dúró, o sì máa gba ìràwọ̀.",
  "Treino livre": "Ìdánrawò òmìnira",
