  "Alta temporada em {lugares}: os aluguéis dobram por uma rodada.": "Àsìkò àwọn arìnrìn-àjò ní {lugares}: owó ilé di ìlọ́po méjì fún ìyípo kan.",
  "As duas diagonais também têm os números de 1 a 9.": "Àwọn ìlà ìdábùú méjèèjì náà ní nọ́ńbà 1 sí 9.",
  "As escuras não fazem dois três abertos de uma vez": "Àwọn dúdú kì í ṣe mẹ́ta ṣíṣí méjì lẹ́ẹ̀kan",
  "As escuras não podem fazer dois três abertos de uma vez.": "Àwọn dúdú kò lè ṣe mẹ́ta ṣíṣí méjì lẹ́ẹ̀kan náà.",
  "Baixa temporada em {lugares}: os aluguéis caem pela metade por uma rodada.": "Àsìkò tí arìnrìn-àjò kò pọ̀ ní {lugares}: owó ilé dín sí ìdajì fún ìyípo kan.",
  "Batidas especiais: carroça e lá-e-ló valem o dobro": "Ìparí àkànṣe: òkúta ìbejì àti lá-e-ló jẹ́ ìlọ́po méjì",
  "Brasil inteiro": "Gbogbo Brazil",
  "Captura: cercar duas pedras do outro tira as duas": "Ìmúni: yíká òkúta méjì ẹnì kejì yóò mú méjèèjì kúrò",
