  "Chá forte": "Tíì líle",
  "Chegou o IPTU: pague {valor} por cidade sua.": "Owó orí ilé ti dé: san {valor} fún ìlú rẹ kọ̀ọ̀kan.",
  "Chuva de estrelas": "Òjò ìràwọ̀",
  "Com a captura, cercar duas pedras do outro entre duas suas tira as duas; cinco capturas também vencem.": "Pẹ̀lú ìmúni, yíká òkúta méjì ẹnì kejì láàárín òkúta rẹ méjì yóò mú méjèèjì kúrò; ìmúni márùn-ún náà borí.",
  "Com a restrição 3-3, as escuras não podem fazer dois três abertos de uma vez.": "Pẹ̀lú ìdínà 3-3, àwọn dúdú kò lè ṣe mẹ́ta ṣíṣí méjì lẹ́ẹ̀kan náà.",
  "Com as batidas especiais, bater com carroça ou com a pedra que serve nas duas pontas vale o dobro; a carroça nas duas pontas, o quádruplo.": "Pẹ̀lú ìparí àkànṣe, píparí pẹ̀lú òkúta ìbejì tàbí òkúta tó bá ìpẹ̀kun méjèèjì mu jẹ́ ìlọ́po méjì; òkúta ìbejì tó bá ìpẹ̀kun méjèèjì mu, ìlọ́po mẹ́rin.",
  "Consulta no dentista: pague {valor}.": "Ìbẹ̀wò sí dókítà eyín: san {valor}.",
  "Copa do Celeiro": "Ife Àká",
  "Cruzada!": "Àgbélébùú!",
  "Cura muito a turma e levanta quem caiu.": "Ó wo ẹgbẹ́ sàn gidigidi ó sì gbé àwọn tó ṣubú dìde.",
  "Defendeu!": "Ó dáàbò bò ó!",
  "Erva-doce": "Fẹ́nẹ́lì",
  "Escolha até {n} bichos para a mesa.": "Yan ẹranko tó tó {n} fún tábìlì.",
  "Escolha quem sai da equipe.": "Yan èyí tí yóò kúrò nínú ẹgbẹ́.",
  "Esquecer qual?": "Gbàgbé èwo?",
  "Feriadão: vá até o Feriado.": "Ìsinmi gígùn: lọ sí Ọjọ́ ìsinmi.",
  "Flecha final": "Ọfà ìkẹyìn",
