  "Gol de ouro no empate": "Góòlù wúrà nígbà ọ̀mì",
  "Golpe de pá": "Ìlù ṣọ́bìrì",
  "Guardar na toca": "Fi pamọ́ sínú ihò",
  "Lá-e-ló!": "Lá-e-ló!",
  "Levar": "Mú lọ",
  "Lotou o show da sua banda: receba {valor}.": "Eré ẹgbẹ́ olórin rẹ kún: gba {valor}.",
  "Magia forte em todos os inimigos.": "Idán líle sí gbogbo ọ̀tá.",
  "Mão de dez: esperando a decisão.": "Ọwọ́ mẹ́wàá: à ń dúró de ìpinnu.",
  "Mão de dez: jogar valendo 4, ou correr e dar 2 pontos?": "Ọwọ́ mẹ́wàá: ṣeré ní iye 4, tàbí sá kí o fún wọn ní àmì 2?",
  "Maratona": "Eré-ìje gígùn",
  "Mineiro": "Mineiro",
  "Mutirão na vizinhança, mas sem onde construir: receba {valor}.": "Àjọṣe iṣẹ́ àdúgbò, ṣùgbọ́n kò sí ibi láti kọ́lé: gba {valor}.",
  "Mutirão na vizinhança: um prédio grátis em {cidade}.": "Àjọṣe iṣẹ́ àdúgbò: ilé kan lọ́fẹ̀ẹ́ ní {cidade}.",
  "Na variante sem comer para trás, a pedra só come para a frente; a dama continua comendo para todo lado.": "Nínú ọ̀nà tí kò jẹ sẹ́yìn, òkúta ń jẹ síwájú nìkan; ọba ṣì ń jẹ sí gbogbo ẹ̀gbẹ́.",
  "Não aprender": "Má kọ́ ọ",
  "Não atire na joaninha: ela é amiga da horta.": "Má ṣe yìnbọn sí kòkòrò pupa náà: ọ̀rẹ́ ọgbà ni.",
  "No meio": "Láàárín",
  "No mineiro não há vira: as manilhas são o 4 de paus, o 7 de copas, o ás de espadas e o 7 de ouros.": "Nínú Mineiro kò sí vira: àwọn manilha ni 4 kílọ́bù, 7 ọkàn, áàsì spéèdì àti 7 dáyámọ́ńdì.",
  "No mineiro, a mão vale 2, e o truco, o seis, o nove e o doze valem 4, 8, 10 e 12. Com 10 pontos, é a mão de dez: jogar valendo 4, ou correr e dar 2.": "Nínú Mineiro, ọwọ́ kan jẹ́ 2, truco, mẹ́fà, mẹ́sàn-án àti méjìlá sì jẹ́ 4, 8, 10 àti 12. Pẹ̀lú àmì 10, ọwọ́ mẹ́wàá ni: ṣeré ní iye 4, tàbí sá kí o fún wọn ní 2.",
  "Noite no Lobisomem: os microfones voltam no amanhecer.": "Òru nínú Ìkookò-ènìyàn: àwọn máíkírófóònù yóò padà ní àfẹ̀mọ́júmọ́.",
  "Noite: microfones desligados": "Òru: a ti pa àwọn máíkírófóònù",
  "O banco perdoou a hipoteca de {cidade}.": "Ilé-ìfowópamọ́ dárí ìdógò {cidade} jì.",
  "O banco perdoou os juros: receba {valor}.": "Ilé-ìfowópamọ́ dárí èlé jì: gba {valor}.",
  "O churrasco foi por sua conta: dê {valor} a cada um.": "Ìwọ lo sanwó ẹran yíyan: fún ẹnìkọ̀ọ̀kan ní {valor}.",
  "O mar de 8 × 8 tem a frota menor, e o de 12 × 12, a maior.": "Òkun 8 × 8 ní ọkọ̀ ojú omi díẹ̀, ti 12 × 12 sì ní púpọ̀.",
  "Obras em {lugares}: cada dono paga {valor} por prédio ali.": "Iṣẹ́ àtúnṣe ní {lugares}: olówó kọ̀ọ̀kan ń san {valor} fún ilé kọ̀ọ̀kan níbẹ̀.",
  "Paulista": "Paulista",
  "Pênaltis": "Pẹ́nárítì",
  "Pneu furado: volte 2 casas.": "Táyà bẹ́: padà sẹ́yìn àpótí 2.",
  "Regra": "Òfin",
  "Rodada bônus: acerte as cenouras que sobem, sem limite de tiros.": "Ìyípo àfikún: yìnbọn sí kárọ́ọ̀tì tó ń gòkè, kò sí òpin ìbọn.",
  "Sem limite de tiros": "Kò sí òpin ìbọn",
  "Seu projeto ganhou a feira de ciências: receba {valor}.": "Iṣẹ́ àkànṣe rẹ borí ní ìfihàn sáyẹ́ǹsì: gba {valor}.",
  "Soltar": "Tú sílẹ̀",
  "Sudoku X": "Sudoku X",
  "Tabuleiro": "Pátákó eré",
  "Tamanho do mar": "Ìtóbi òkun",
  "Toque numa resposta que não vale. Com dois, ela só cai se quem escreveu aceitar.": "Tẹ ìdáhùn tí kò wúlò. Tí ẹ bá jẹ́ méjì, yóò kúrò kìkì tí ẹni tó kọ ọ́ bá gbà.",
