  "No dominó de pontos, quem deixa as pontas somando 5, 10, 15… marca a soma na hora; a carroça na ponta conta as duas metades. A partida vai a 150.": "Nínú dómínò àmì, ẹni tó bá jẹ́ kí àpapọ̀ àwọn ìpẹ̀kun jẹ́ 5, 10, 15… máa gba àpapọ̀ náà lẹ́sẹ̀kẹsẹ̀; òkúta ìlọ́po-méjì ní ìpẹ̀kun ń ka àbọ̀ méjèèjì. Eré náà máa lọ dé 150.",
  "No fim, as setas embaixo do tabuleiro andam pela partida, lance a lance.": "Ní òpin, àwọn ọfà tó wà nísàlẹ̀ pátákó máa ń lọ káàkiri eré náà, ìgbésẹ̀ kan lẹ́yìn òmíràn.",
