  "No tabuleiro de 10 × 10, as internacionais, são 20 pedras de cada lado; a regra é a mesma.": "Lórí pátákó 10 × 10, ti àgbáyé, òkúta 20 ló wà ní ẹ̀gbẹ́ kọ̀ọ̀kan; òfin kan náà ni.",
