  "Qual é o rio com mais água do mundo?": "Odò wo ló ní omi jù lágbàáyé?",
  "Qual órgão bombeia o sangue pelo corpo?": "Ẹ̀yà ara wo ló ń fa ẹ̀jẹ̀ káàkiri ara?",
  "Qual planeta é conhecido como o planeta vermelho?": "Pílánẹ́ẹ̀tì wo la mọ̀ sí pílánẹ́ẹ̀tì pupa?",
  "Qual planeta fica mais perto do Sol?": "Pílánẹ́ẹ̀tì wo ló súnmọ́ Oòrùn jù?",
  "Qual sólido tem seis faces quadradas?": "Ohun líle wo ló ní ojú onígun mẹ́rin mẹ́fà?",
  "Quantas asas tem uma borboleta?": "Ìyẹ́ apá mélòó ni labalábá ní?",
  "Quantas cores tem o arco-íris, na conta mais comum?": "Àwọ̀ mélòó ni òṣùmàrè ní, gẹ́gẹ́ bí wọ́n ṣe sábà ń kà á?",
  "Quantas horas tem um dia?": "Wákàtí mélòó ló wà nínú ọjọ́ kan?",
  "Quanto é dez menos três?": "Èló ni mẹ́wàá yọ mẹ́ta?",
