  "Quanto é o dobro de seis?": "Èló ni ìlọ́po méjì mẹ́fà?",
  "Quanto é sete vezes oito?": "Èló ni méje ní ìlọ́po mẹ́jọ?",
  "Quanto é três mais quatro?": "Èló ni mẹ́ta àti mẹ́rin?",
  "Quanto tempo a Terra leva para dar uma volta em torno do Sol?": "Ìgbà mélòó ni Ayé fi ń yí Oòrùn ká lẹ́ẹ̀kan?",
  "Quanto tempo a Terra leva para girar em torno de si mesma?": "Ìgbà mélòó ni Ayé fi ń yí ara rẹ̀ po lẹ́ẹ̀kan?",
