  "Quantos anos tem uma década?": "Ọdún mélòó ló wà nínú ẹ̀wádún kan?",
  "Quantos braços tem um polvo?": "Apá mélòó ni ẹja ọlọ́wọ́-mẹ́jọ (octopus) ní?",
  "Quantos centímetros tem um metro?": "Sẹ̀ǹtímítà mélòó ló wà nínú mítà kan?",
  "Quantos dentes tem um adulto, normalmente?": "Eyín mélòó ni àgbàlagbà sábà máa ń ní?",
  "Quantos dias tem um ano que não é bissexto?": "Ọjọ́ mélòó ló wà nínú ọdún tí kì í ṣe ọdún ẹlẹ́gbẹ̀ta-ó-lé-mẹ́fà?",
  "Quantos dias tem uma semana?": "Ọjọ́ mélòó ló wà nínú ọ̀sẹ̀ kan?",
  "Quantos gramas tem um quilo?": "Gíráàmù mélòó ló wà nínú kílò kan?",
  "Quantos jogadores um time de futebol tem em campo?": "Agbábọ́ọ̀lù mélòó ni ẹgbẹ́ bọ́ọ̀lù-àfẹsẹ̀gbá kan ní lórí pápá?",
