  "Quantos lados tem um quadrado?": "Ẹ̀gbẹ́ mélòó ni onígun mẹ́rin dọ́gba ní?",
  "Quantos lados tem um triângulo?": "Ẹ̀gbẹ́ mélòó ni onígun mẹ́ta ní?",
