  "Saara": "Sàhárà",
  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "Ẹranko àṣírí kan jáde, ẹnì kọ̀ọ̀kan sì ń dábàá àwọn mìíràn. Àbá kọ̀ọ̀kan ń fi ohun tó bá àṣírí mu hàn: ìsọ̀rí, oúnjẹ, ibi tó ń gbé àti ìwúwo. Ẹni tó bá gbà á pẹ̀lú àbá díẹ̀ jù ló ń gba àmì púpọ̀ jù.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "Dáínósọ̀ àṣírí kan jáde, ẹnì kọ̀ọ̀kan sì ń dábàá àwọn mìíràn. Àbá kọ̀ọ̀kan ń fi ohun tó bá àṣírí mu hàn: sáà, oúnjẹ, ẹgbẹ́, gígùn àti ibi tí wọ́n ti rí i. Ẹni tó bá gbà á pẹ̀lú àbá díẹ̀ jù ló ń gba àmì púpọ̀ jù.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "Èròjà kẹ́míkà àṣírí kan jáde, ẹnì kọ̀ọ̀kan sì ń dábàá àwọn mìíràn. Àbá kọ̀ọ̀kan ń fi ohun tó bá àṣírí mu hàn: ìdílé, ìpò ara, sáà, ẹgbẹ́ àti nọ́ńbà átọ́mù. Ẹni tó bá gbà á pẹ̀lú àbá díẹ̀ jù ló ń gba àmì púpọ̀ jù.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "Ìpínlẹ̀ àṣírí kan ní Bùràsílì jáde, ẹnì kọ̀ọ̀kan sì ń dábàá àwọn mìíràn. Àbá kọ̀ọ̀kan ń fi jíjìnnà àti ìhà sí àṣírí hàn, agbègbè, iye ènìyàn, fífẹ̀ ilẹ̀, etí òkun àti ààlà pẹ̀lú orílẹ̀-èdè mìíràn. Ẹni tó bá gbà á pẹ̀lú àbá díẹ̀ jù ló ń gba àmì púpọ̀ jù.",
