  "Você aguenta o primeiro ataque dos lobisomens. Ninguém fica sabendo.": "O lè fara da ìkọlù àkọ́kọ́ àwọn ìkookò-ènìyàn. Kò sẹ́ni tó máa mọ̀.",
  "Você colheu {n} recursos.": "O ti kó ohun àlùmọ́ọ́nì {n} jọ.",
  "Você joga por conta própria: vence se a vila tirar você do jogo no julgamento. Levante suspeitas, mas sem exagero.": "O ń ṣeré fún ara rẹ: o borí tí abúlé bá yọ ọ́ kúrò nínú eré nígbà ìdájọ́. Mú kí wọ́n fura sí ọ, ṣùgbọ́n má ṣe é jù.",
