  "{pessoa} sai da comunidade e das chamadas dela na hora, e só volta se alguém que administra desbanir.": "{pessoa} yóò kúrò nínú àwùjọ àti àwọn ìpè rẹ̀ lẹ́sẹ̀kẹsẹ̀, yóò sì padà wá nìkan tí alákòóso kan bá mú òfin náà kúrò.",
  "Quem administra esta comunidade baniu a sua conta, e por isso não dá para entrar.": "Àwọn tó ń ṣàkóso àwùjọ yìí ti fòfin de àkáǹtì rẹ, nítorí náà o kò lè wọlé.",
  "Só quem administra a comunidade pode banir alguém.": "Àwọn tó ń ṣàkóso àwùjọ nìkan ló lè fòfin de ẹnikẹ́ni.",
  "Só quem administra a comunidade pode desbanir alguém.": "Àwọn tó ń ṣàkóso àwùjọ nìkan ló lè mú òfin kúrò lórí ẹnikẹ́ni.",
  "Essa pessoa não está banida.": "A kò fòfin de ẹni yìí.",
  "Só quem administra a comunidade fixa mensagens.": "Àwọn tó ń ṣàkóso àwùjọ nìkan ló ń gún ìfiránṣẹ́ mọ́.",
  "Só as mensagens do canal podem ser fixadas, não as de um tópico.": "Ìfiránṣẹ́ ìkànnì nìkan ni a lè gún mọ́, kì í ṣe ti òkùn.",
  "Este canal já tem 50 mensagens fixadas. Desafixe uma antes.": "Ìkànnì yìí ti ní ìfiránṣẹ́ 50 tí a gún mọ́. Kọ́kọ́ yọ ọ̀kan kúrò.",
