  "Canais de avisos": "Àwọn ìkànnì ìkéde",
  "Num canal de avisos, só quem administra escreve. A turma lê, reage e conversa nos tópicos de cada aviso.": "Nínú ìkànnì ìkéde, àwọn tó ń ṣàkóso nìkan ló ń kọ̀wé. Àwọn yòókù ń kà á, ń fèsì, wọ́n sì ń sọ̀rọ̀ nínú àwọn òkùn ìkéde kọ̀ọ̀kan.",
