  "Convite não encontrado.": "A kò rí ìpè náà.",
  "Só quem criou o convite, ou quem administra a comunidade, pode revogá-lo.": "Ẹni tó ṣẹ̀dá ìpè náà, tàbí àwọn tó ń ṣàkóso àwùjọ, nìkan ló lè fagi lé e.",
  "Só quem administra a comunidade vê o registro de moderação.": "Àwọn tó ń ṣàkóso àwùjọ nìkan ló lè rí àkọsílẹ̀ ìṣàkóso.",
